using System.Reflection;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;

namespace Company.Identity.PermissionRegistration;

/// <summary>
/// Background service that discovers <c>[RequirePermission]</c> attributes from an assembly,
/// builds a manifest and registers it with the Identity Facade using exponential backoff.
/// Catches all exceptions — registration failure never blocks application startup.
/// </summary>
internal sealed class PermissionRegistrationHostedService(
    IPermissionRegistrationClient client,
    IOptions<PermissionRegistrationOptions> options,
    ILogger<PermissionRegistrationHostedService> logger) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        var opts = options.Value;
        var assembly = opts.RegistrationAssembly ?? Assembly.GetEntryAssembly();
        if (assembly is null)
        {
            logger.LogDebug("No assembly available for permission registration — skipping");
            return;
        }

        var manifest = PermissionManifest.Create(opts, assembly);

        for (var attempt = 0; attempt <= opts.MaximumRetries; attempt++)
        {
            if (stoppingToken.IsCancellationRequested) return;
            try
            {
                var response = await client.RegisterAsync(manifest, stoppingToken);
                if (response is { Accepted: true })
                {
                    logger.LogInformation(
                        "Permission manifest registered for {ServiceId} v{Version} " +
                        "({PermissionCount} permissions, attempt {Attempt})",
                        manifest.ServiceId, manifest.ServiceVersion, manifest.Permissions.Count, attempt + 1);
                    return;
                }

                logger.LogWarning("Permission registration not accepted for {ServiceId} (attempt {Attempt})",
                    manifest.ServiceId, attempt + 1);
            }
            catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
            {
                return;
            }
            catch (Exception ex)
            {
                logger.LogWarning(ex, "Permission registration failed for {ServiceId} (attempt {Attempt})",
                    manifest.ServiceId, attempt + 1);
            }

            if (attempt < opts.MaximumRetries)
            {
                var delay = opts.InitialRetryDelay * Math.Pow(2, Math.Min(attempt, 5));
                try
                {
                    await Task.Delay(delay, stoppingToken);
                }
                catch (OperationCanceledException)
                {
                    return;
                }
            }
        }

        logger.LogWarning(
            "Permission registration incomplete for {ServiceId} after {MaxRetries} attempts — " +
            "the application continues without registered permissions",
            manifest.ServiceId, opts.MaximumRetries);
    }
}

/// <summary>
/// Registers the permission discovery + registration pipeline: scans for
/// <c>[RequirePermission]</c> attributes at startup and pushes the manifest to the
/// Identity Facade in the background. Failure never prevents app start.
/// </summary>
public static class PermissionRegistrationExtensions
{
    /// <summary>
    /// Registers the permission registration background service. Scans the entry assembly
    /// (or <paramref name="assembly"/> when provided) for <c>[RequirePermission]</c> attributes.
    /// </summary>
    public static IServiceCollection AddPermissionRegistration(
        this IServiceCollection services,
        Action<PermissionRegistrationOptions> configure)
        => services.AddPermissionRegistration(null, configure);

    /// <inheritdoc cref="AddPermissionRegistration(IServiceCollection,Action{PermissionRegistrationOptions})"/>
    /// <param name="assembly">Explicit assembly to scan; defaults to the entry assembly.</param>
    public static IServiceCollection AddPermissionRegistration(
        this IServiceCollection services,
        Assembly? assembly,
        Action<PermissionRegistrationOptions> configure)
    {
        services.Configure<PermissionRegistrationOptions>(o =>
        {
            configure(o);
            if (assembly is not null) o.RegistrationAssembly = assembly;
        });

        services.AddHttpClient<IPermissionRegistrationClient, PermissionRegistrationClient>();
        services.AddHostedService<PermissionRegistrationHostedService>();
        return services;
    }
}---
using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.Options;

namespace Company.Identity.PermissionRegistration;

/// <summary>
/// Client-side representation of the <c>POST /api/identity/permissions/register</c> response.
/// Decoupled from <c>Identity.Contracts</c> so external consumers of this package never need
/// a reference to the facade's contract assembly.
/// </summary>
public sealed record RegistrationResponse(
    string ServiceId,
    string ManifestVersion,
    string ManifestHash,
    bool Accepted,
    IReadOnlyCollection<string> DeprecatedPermissions);

/// <summary>
/// Registers discovered permissions with the Identity Facade. The service token is obtained
/// <b>through the facade's own auth proxy</b> (<c>POST /api/identity/auth/login</c>) with the
/// client-credentials grant — the consuming service never needs to know where Keycloak is.
/// Returns <c>null</c> on transient failure (caller retries).
/// </summary>
public interface IPermissionRegistrationClient
{
    Task<RegistrationResponse?> RegisterAsync(PermissionManifest manifest, CancellationToken ct);
}

internal sealed class PermissionRegistrationClient(
    HttpClient http,
    IOptions<PermissionRegistrationOptions> opts) : IPermissionRegistrationClient
{
    private readonly PermissionRegistrationOptions _o = opts.Value;

    private static readonly JsonSerializerOptions s_json = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase
    };

    public async Task<RegistrationResponse?> RegisterAsync(PermissionManifest manifest, CancellationToken ct)
    {
        var token = await GetTokenViaFacadeAsync(ct);
        if (string.IsNullOrEmpty(token)) return null;

        var registerUrl = $"{_o.IdentityServer.ToString().TrimEnd('/')}/api/identity/permissions/register";
        try
        {
            var req = new HttpRequestMessage(HttpMethod.Post, registerUrl)
            {
                Content = JsonContent.Create(manifest, options: s_json)
            };
            req.Headers.Add("Authorization", $"Bearer {token}");
            var res = await http.SendAsync(req, ct);
            return res.IsSuccessStatusCode
                ? await res.Content.ReadFromJsonAsync<RegistrationResponse>(s_json, ct)
                : null;
        }
        catch
        {
            return null;
        }
    }

    /// <summary>
    /// POSTs the client-credentials grant to the facade's login proxy, which forwards it to
    /// Keycloak. Only <c>IdentityServer</c>, <c>ClientId</c> and <c>ClientSecret</c> are needed —
    /// no Keycloak URL, realm, or secret is configured in the consuming service.
    /// </summary>
    private async Task<string> GetTokenViaFacadeAsync(CancellationToken ct)
    {
        if (string.IsNullOrEmpty(_o.ClientId) || string.IsNullOrEmpty(_o.ClientSecret)) return string.Empty;
        var loginUrl = $"{_o.IdentityServer.ToString().TrimEnd('/')}/api/identity/auth/login";
        try
        {
            var res = await http.PostAsync(loginUrl, new FormUrlEncodedContent(new Dictionary<string, string>
            {
                ["grant_type"] = "client_credentials",
                ["client_id"] = _o.ClientId,
                ["client_secret"] = _o.ClientSecret,
            }), ct);
            if (!res.IsSuccessStatusCode) return string.Empty;
            var doc = JsonDocument.Parse(await res.Content.ReadAsStringAsync(ct));
            return doc.RootElement.TryGetProperty("access_token", out var t)
                ? t.GetString() ?? string.Empty
                : string.Empty;
        }
        catch
        {
            return string.Empty;
        }
    }
}---
using System.Reflection;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Company.Identity.Abstractions;

namespace Company.Identity.PermissionRegistration;

public sealed class PermissionRegistrationOptions
{
    public required Uri IdentityServer { get; set; }
    public required string ServiceName { get; set; }
    public string ServiceId { get; set; } = string.Empty;
    public string ServiceVersion { get; set; } = "0.0.0";
    public string ManifestVersion { get; set; } = "1";
    public TimeSpan InitialRetryDelay { get; set; } = TimeSpan.FromSeconds(2);
    public int MaximumRetries { get; set; } = 8;

    // Service client credentials, sent through the facade's login proxy — no Keycloak config needed.
    public string? ClientId { get; set; }
    public string? ClientSecret { get; set; }

    // Assembly to scan for [RequirePermission] attributes. Defaults to the entry assembly.
    internal Assembly? RegistrationAssembly { get; set; }
}

public sealed record PermissionManifest(
    string ServiceId,
    string ServiceVersion,
    string ManifestVersion,
    IReadOnlyCollection<PermissionDescriptor> Permissions,
    string ManifestHash)
{
    public static PermissionManifest Create(PermissionRegistrationOptions options, Assembly assembly)
    {
        var permissions = assembly.GetTypes().SelectMany(type => type
                .GetCustomAttributes<RequirePermissionAttribute>(true)
                .Select(attribute => new PermissionDescriptor(attribute.Name,
                    $"Permission for {type.FullName ?? type.Name}", type.Namespace ?? string.Empty))
                .Concat(type
                    .GetMethods(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance |
                                BindingFlags.Static)
                    .SelectMany(method => method.GetCustomAttributes<RequirePermissionAttribute>(true)
                        .Select(attribute => new PermissionDescriptor(attribute.Name,
                            $"Permission for {method.DeclaringType?.FullName ?? type.Name}.{method.Name}",
                            type.Namespace ?? string.Empty)))))
            .Where(x => !string.IsNullOrWhiteSpace(x.Name)).DistinctBy(x => x.Name, StringComparer.Ordinal)
            .OrderBy(x => x.Name, StringComparer.Ordinal).ToArray();
        var serviceId = string.IsNullOrWhiteSpace(options.ServiceId) ? options.ServiceName : options.ServiceId;
        var canonical = JsonSerializer.Serialize(new
        {
            serviceId, serviceVersion = options.ServiceVersion, manifestVersion = options.ManifestVersion, permissions
        });
        var hash = "sha256:" +
                   Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(canonical))).ToLowerInvariant();
        return new(serviceId, options.ServiceVersion, options.ManifestVersion, permissions, hash);
    }
