public sealed class OpenApiTests
{
    [Fact]
    public async Task OpenApi_Contains_New_Endpoints()
    {
        // Lightweight probe: spawn the API on an ephemeral port and fetch the document.
        // No live Keycloak required — the document is produced before any outbound call.
        var app = await TestHost.StartAsync();
        try
        {
            using var client = new System.Net.Http.HttpClient();
            var json = await client.GetStringAsync($"{app.Url}/openapi/v1.json");
            using var doc2 = System.Text.Json.JsonDocument.Parse(json);
            var paths = doc2.RootElement.GetProperty("paths");
            string[] required =
            [
                "/api/identity/business-roles",
                "/api/identity/business-roles/{name}",
                "/api/identity/business-roles/{name}/effective-permissions",
                "/api/identity/users/{id}/scoped-access",
                "/api/identity/access-context",
            ];
            foreach (var p in required)
                Assert.True(paths.TryGetProperty(p, out _), $"missing OpenAPI path {p}");
        }
        finally { await app.DisposeAsync(); }
    }

    private sealed class TestHost : IAsyncDisposable
    {
        private readonly Microsoft.AspNetCore.Hosting.IWebHost _host;
        public string Url { get; }
        private TestHost(Microsoft.AspNetCore.Hosting.IWebHost host, string url) { _host = host; Url = url; }
        public static async Task<TestHost> StartAsync()
