2	using Company.Identity.Authorization.AspNetCore;
3	using Company.Identity.PermissionRegistration;
4	using Scalar.AspNetCore;
5	using SampleApp;
6	
7	var builder = WebApplication.CreateBuilder(args);
8	
9	var authority = builder.Configuration["Identity:Authority"] ?? "http://localhost:8080/realms/company";
10	var audience = builder.Configuration["Identity:Audience"] ?? string.Empty;
11	
12	// Authority is the Identity Facade itself — the facade proxies OIDC discovery + JWKS and
13	// rewrites jwks_uri to itself, so this service never learns where Keycloak is.
14	// AcceptIssuerFromDiscovery validates the issuer claim from the proxied discovery document
15	// (the genuine Keycloak issuer) instead of the facade URL.
16	builder.Services.AddCompanyAuthentication(options =>
17	{
18	    options.Authority = authority;
19	    options.Audience = audience;
20	    options.RequireHttpsMetadata = !builder.Environment.IsDevelopment();
21	    options.AcceptIssuerFromDiscovery = true;
22	});
23	builder.Services.AddCompanyAuthorization();
24	builder.Services.AddCompanyAccessContext();
25	builder.Services.AddSingleton<OrderService>();
26	
27	// Discover [RequirePermission] attributes in this assembly and push the manifest to the
28	// Identity Facade in the background. Registration failure never blocks startup.
29	builder.Services.AddPermissionRegistration(o =>
30	{
31	    o.IdentityServer = new Uri(builder.Configuration["PermissionRegistration:IdentityServer"] ??
32	                               "http://localhost:5080");
33	    o.ServiceName = "order-service";
34	    o.ServiceVersion = typeof(Program).Assembly.GetName().Version?.ToString(3) ?? "1.0.0";
35	    o.ClientId = builder.Configuration["PermissionRegistration:ClientId"] ?? "order-service";
36	    o.ClientSecret = builder.Configuration["PermissionRegistration:ClientSecret"];
37	    o.InitialRetryDelay = TimeSpan.FromSeconds(2);
38	    o.MaximumRetries = 8;
39	});
40	
41	// Scalar API reference + OpenAPI document — every guarded endpoint is listed with its
42	// required permission and accepts a Bearer token from the facade login proxy.
43	builder.Services.AddOpenApi("v1", o =>
44	{
45	    o.AddDocumentTransformer((document, _, _) =>
46	    {
47	        document.Info.Title = "Order Service (sample)";
48	        document.Info.Description =
