184	{
185	    private sealed class FakeBusinessRoleStore : IBusinessRoleStore
186	    {
187	        private readonly Dictionary<string, BusinessRoleDto> _roles = new(StringComparer.Ordinal);
188	        public Task<BusinessRoleDto?> GetAsync(string name, CancellationToken ct) => Task.FromResult(_roles.TryGetValue(name, out var v) ? v : null);
189	        public Task<IReadOnlyCollection<BusinessRoleDto>> ListAsync(CancellationToken ct) => Task.FromResult((IReadOnlyCollection<BusinessRoleDto>)_roles.Values.ToArray());
190	        public Task<BusinessRoleDto> CreateAsync(string name, string? desc, IReadOnlyCollection<string> perms, CancellationToken ct)
191	        {
192	            if (_roles.ContainsKey(name)) throw new InvalidOperationException("exists");
193	            var dto = new BusinessRoleDto(name, desc, true, perms.ToArray());
194	            _roles[name] = dto; return Task.FromResult(dto);
195	        }
196	        public Task<BusinessRoleDto?> UpdateAsync(string name, string? desc, CancellationToken ct)
197	        {
198	            if (!_roles.TryGetValue(name, out var cur)) return Task.FromResult<BusinessRoleDto?>(null);
199	            var next = cur with { Description = desc }; _roles[name]=next; return Task.FromResult<BusinessRoleDto?>(next);
200	        }
201	        public Task<bool> DeleteAsync(string name, CancellationToken ct) => Task.FromResult(_roles.Remove(name));
202	        public Task<IReadOnlyCollection<string>> GetEffectivePermissionsAsync(string name, CancellationToken ct)
203	            => Task.FromResult(_roles.TryGetValue(name,out var r) ? r.Permissions : (IReadOnlyCollection<string>)Array.Empty<string>());
204	        public Task AddPermissionsAsync(string name, IReadOnlyCollection<string> perms, CancellationToken ct)
205	        {
206	            if (!_roles.TryGetValue(name, out var cur)) throw new KeyNotFoundException(name);
207	            _roles[name] = cur with { Permissions = cur.Permissions.Concat(perms).Distinct(StringComparer.Ordinal).ToArray() };
208	            return Task.CompletedTask;
209	        }
210	        public Task RemovePermissionAsync(string name, string perm, CancellationToken ct)
211	        {
212	            if (_roles.TryGetValue(name,out var cur)) _roles[name]=cur with{Permissions=cur.Permissions.Where(p=>p!=perm).ToArray()};
213	            return Task.CompletedTask;
214	        }
215	    }
