     ```csharp
     public sealed class FacadeResolvingAccessContext : ICurrentAccessContext {
       private readonly ClaimsPrincipal _principal; private readonly IHttpContextAccessor _httpAccessor; private readonly IHttpClientFactory _httpFactory; private readonly AccessContextOptions _options;
       private ClaimsPrincipalAccessContext _inner; private bool _resolved; private readonly object _gate = new();
       public FacadeResolvingAccessContext(ClaimsPrincipal principal, IHttpContextAccessor httpAccessor, IHttpClientFactory httpFactory, IOptions<AccessContextOptions> options) { _principal=principal; _httpAccessor=httpAccessor; _httpFactory=httpFactory; _options=options.Value; _inner=new ClaimsPrincipalAccessContext(principal); }
       public async Task EnsureLoadedAsync(CancellationToken ct = default) {
         if (_resolved) return; if (string.IsNullOrWhiteSpace(_options.FacadeBaseUrl)) return; if (_inner.HasInlineAssignments) { _resolved=true; return; }
         var authorization = _httpAccessor.HttpContext?.Request.Headers.Authorization.ToString();
         if (!AuthenticationHeaderValue.TryParse(authorization, out var header) || !string.Equals(header.Scheme,"Bearer",StringComparison.OrdinalIgnoreCase)) return;
         var url = _options.FacadeBaseUrl!.TrimEnd('/') + _options.AccessContextPath;
         try { using var cts=CancellationTokenSource.CreateLinkedTokenSource(ct); cts.CancelAfter(_options.Timeout); var client=_httpFactory.CreateClient("IdentityAccessContext"); using var req=new HttpRequestMessage(HttpMethod.Get,url); req.Headers.Authorization=new AuthenticationHeaderValue("Bearer",header.Parameter); using var resp=await client.SendAsync(req,cts.Token); if(!resp.IsSuccessStatusCode) return; var dto=JsonSerializer.Deserialize<AccessContextResponse>(await resp.Content.ReadAsStringAsync(cts.Token), new JsonSerializerOptions{PropertyNamingPolicy=JsonNamingPolicy.CamelCase}); lock(_gate){ if(_resolved) return; var effectivePerms=permissions.Length>0?permissions:_inner.Permissions.ToArray(); _inner=new ClaimsPrincipalAccessContext(effectivePerms,assignments); _resolved=true; } } catch(OperationCanceledException){} catch{}
       }
     }
     ```
