     ```csharp
     public static class AccessContextExtensions {
       public static IServiceCollection AddCompanyAccessContext(this IServiceCollection services){ services.Configure<AccessContextOptions>(_=>{}); return services.AddCompanyAccessContextCore(); }
       public static IServiceCollection AddCompanyAccessContext(this IServiceCollection services, Action<AccessContextOptions> configure){ services.Configure(configure); return services.AddCompanyAccessContextCore(); }
       private static IServiceCollection AddCompanyAccessContextCore(this IServiceCollection services){
         services.AddHttpContextAccessor(); services.AddHttpClient("IdentityAccessContext");
         services.AddScoped<ICurrentAccessContext>(sp=>{ var accessor=sp.GetRequiredService<IHttpContextAccessor>(); var principal=accessor.HttpContext?.User??new ClaimsPrincipal(); var opts=sp.GetRequiredService<IOptions<AccessContextOptions>>(); if(string.IsNullOrWhiteSpace(opts.Value.FacadeBaseUrl)) return new ClaimsPrincipalAccessContext(principal); var factory=sp.GetRequiredService<IHttpClientFactory>(); return new FacadeResolvingAccessContext(principal,accessor,factory,opts); });
         return services;
       }
     }
