46	        // Realm role mappings are applied after the attribute so that a failure there can still be compensated by
47	        // dropping the attribute entry for the partially mapped role — but simpler is to keep both together and
48	        // roll back the user.
49	        try
50	        {
51	            var doc = ToDocument(request.Assignments);
52	            await scopedStore.SetAsync(created.Id, doc, ct);
53	            foreach (var a in request.Assignments)
54	                await SafeMapRoleAsync(created.Id, a.Role, ct);
55	            return (created, doc);
56	        }
57	        catch (Exception ex)
58	        {
59	            try { await users.DeleteUserAsync(created.Id, ct); } catch { }
60	            throw new InvalidOperationException($"User '{request.Username}' was not created because scoped assignment failed: {ex.Message}", ex);
61	        }
62	    }
