64	    /// <summary>Add or merge a scoped assignment for an existing user: attribute merge + realm role mapping.</summary>
65	    public async Task<ScopedAccessDocument> AddScopedAssignmentAsync(
66	        string userId, ScopedRoleAssignmentDto assignment, CancellationToken ct)
67	    {
68	        var role = await roles.GetAsync(assignment.Role, ct);
69	        if (role is null) throw new InvalidOperationException($"Role '{assignment.Role}' does not exist.");
70	        await scopedStore.AddAssignmentAsync(userId, assignment, ct);
71	        await SafeMapRoleAsync(userId, assignment.Role, ct);
72	        return await scopedStore.GetAsync(userId, ct);
73	    }
