76	        string userId, IReadOnlyCollection<ScopedRoleAssignmentDto> assignments, CancellationToken ct)
77	    {
78	        foreach (var a in assignments)
79	        {
80	            ScopedAccessSerializer.Validate(a);
81	            var role = await roles.GetAsync(a.Role, ct);
82	            if (role is null) throw new InvalidOperationException($"Role '{a.Role}' does not exist.");
83	        }
84	        var previous = await scopedStore.GetAsync(userId, ct);
85	        var previousRoles = previous.Assignments.Select(a => a.Role).ToHashSet(StringComparer.Ordinal);
86	        var nextRoles = assignments.Select(a => a.Role.Trim()).ToHashSet(StringComparer.Ordinal);
87	        var doc = ToDocument(assignments);
88	        await scopedStore.SetAsync(userId, doc, ct);
89	        foreach (var r in nextRoles.Except(previousRoles, StringComparer.Ordinal))
90	            await SafeMapRoleAsync(userId, r, ct);
91	        foreach (var r in previousRoles.Except(nextRoles, StringComparer.Ordinal))
92	            await SafeUnmapRoleAsync(userId, r, ct);
