1	using Company.Identity.Authentication.AspNetCore;
2	using Company.Identity.Authorization.AspNetCore;
3	using Company.Identity.PermissionRegistration;
4	using Scalar.AspNetCore;
5	using SampleApp;
6	
7	var builder = WebApplication.CreateBuilder(args);
8	
9	var authority = builder.Configuration["Identity:Authority"] ?? "http://localhost:8080/realms/company";
10	var audience = builder.Configuration["Identity:Audience"] ?? string.Empty;
11	
12	// Authority is the Identity Facade itself — the facade proxies OIDC discovery + JWKS and
13	// rewrites jwks_uri to itself, so this service never learns where Keycloak is.
14	// AcceptIssuerFromDiscovery validates the issuer claim from the proxied discovery document
15	// (the genuine Keycloak issuer) instead of the facade URL.
16	builder.Services.AddCompanyAuthentication(options =>
17	{
18	    options.Authority = authority;
19	    options.Audience = audience;
20	    options.RequireHttpsMetadata = !builder.Environment.IsDevelopment();
21	    options.AcceptIssuerFromDiscovery = true;
22	});
23	builder.Services.AddCompanyAuthorization();
24	builder.Services.AddCompanyAccessContext(o =>
25	{
26	    // Never point at Keycloak directly — always resolve via the facade that already proxies OIDC.
27	    // Wire from the same setting consumers already configure for auth.
28	    var facade = builder.Configuration["Identity:AccessContext:FacadeBaseUrl"]
29	                 ?? builder.Configuration["PermissionRegistration:IdentityServer"]
30	                 ?? builder.Configuration["Identity:Authority"];
31	    o.FacadeBaseUrl = string.IsNullOrWhiteSpace(facade) ? null : facade.TrimEnd('/');
32	});
33	builder.Services.AddSingleton<OrderService>();
34	
35	// Discover [RequirePermission] attributes in this assembly and push the manifest to the
36	// Identity Facade in the background. Registration failure never blocks startup.
37	builder.Services.AddPermissionRegistration(o =>
38	{
39	    o.IdentityServer = new Uri(builder.Configuration["PermissionRegistration:IdentityServer"] ??
40	                               "http://localhost:5080");
41	    o.ServiceName = "order-service";
42	    o.ServiceVersion = typeof(Program).Assembly.GetName().Version?.ToString(3) ?? "1.0.0";
43	    o.ClientId = builder.Configuration["PermissionRegistration:ClientId"] ?? "order-service";
44	    o.ClientSecret = builder.Configuration["PermissionRegistration:ClientSecret"];
45	    o.InitialRetryDelay = TimeSpan.FromSeconds(2);
46	    o.MaximumRetries = 8;
47	});
48	
49	// Scalar API reference + OpenAPI document — every guarded endpoint is listed with its
50	// required permission and accepts a Bearer token from the facade login proxy.
51	builder.Services.AddOpenApi("v1", o =>
52	{
53	    o.AddDocumentTransformer((document, _, _) =>
54	    {
55	        document.Info.Title = "Order Service (sample)";
56	        document.Info.Description =
57	            "Sample consumer of the Identity Facade. Every endpoint requires one of the ten " +
58	            "Orders.* permissions this service registered at startup via [RequirePermission]. " +
59	            "Get a token from POST /api/identity/auth/login on the Identity Facade and paste it " +
60	            "into the Bearer authentication dialog.";
61	        var components = document.Components ?? new Microsoft.OpenApi.OpenApiComponents();
62	        document.Components = components;
63	        components.SecuritySchemes ??= new Dictionary<string, Microsoft.OpenApi.IOpenApiSecurityScheme>();
64	        components.SecuritySchemes["Bearer"] = new Microsoft.OpenApi.OpenApiSecurityScheme
65	        {
66	            Type = Microsoft.OpenApi.SecuritySchemeType.Http,
67	            Scheme = "bearer",
68	            BearerFormat = "JWT",
69	            Description = "Keycloak-issued JWT obtained through the Identity Facade"
70	        };
71	        document.Security =
72	        [
73	            new Microsoft.OpenApi.OpenApiSecurityRequirement
74	            {
75	                [new Microsoft.OpenApi.OpenApiSecuritySchemeReference("Bearer", document)] = []
76	            }
77	        ];
78	        return Task.CompletedTask;
79	    });
80	});
81	
82	var app = builder.Build();
83	app.UseAuthentication();
84	app.UseAuthorization();
85	
86	app.MapOpenApi();
87	if (app.Environment.IsDevelopment())
88	{
89	    app.MapScalarApiReference(options => options
90	        .WithTitle("Order Service (sample)")
91	        .WithOpenApiRoutePattern("/openapi/v1.json")
92	        .AddPreferredSecuritySchemes(["Bearer"]));
93	}
94	
95	app.MapGet("/health/live", () => Results.Ok(new { status = "alive" }));
96	
97	// One endpoint per permission — the policy name IS the permission name, resolved dynamically
98	// by PermissionPolicyProvider and enforced against the token's permission claims.
99	app.MapGet("/api/orders", (OrderService svc) => Results.Ok(svc.ListOrders()))
100	    .RequireAuthorization(OrderPermissions.ViewOrders).WithTags("Orders");
101	
102	app.MapPost("/api/orders", (string customerUsername, decimal total, OrderService svc) =>
103	        Results.Ok(svc.CreateOrder(customerUsername, total)))
104	    .RequireAuthorization(OrderPermissions.CreateOrders).WithTags("Orders");
105	
106	app.MapPut("/api/orders/{orderId}/total", (string orderId, decimal newTotal, OrderService svc) =>
107	        Results.Ok(svc.EditOrder(orderId, newTotal)))
108	    .RequireAuthorization(OrderPermissions.EditOrders).WithTags("Orders");
109	
110	app.MapPost("/api/orders/{orderId}/cancel", (string orderId, OrderService svc) =>
111	        Results.Ok(svc.CancelOrder(orderId)))
112	    .RequireAuthorization(OrderPermissions.CancelOrders).WithTags("Orders");
113	
114	app.MapGet("/api/orders/{orderId}/invoices", (string orderId, OrderService svc) =>
115	        Results.Ok(svc.ListInvoices(orderId)))
116	    .RequireAuthorization(OrderPermissions.ViewInvoices).WithTags("Invoices");
117	
118	app.MapPost("/api/orders/{orderId}/invoices/issue", (string orderId, OrderService svc) =>
119	        Results.Ok(svc.IssueInvoice(orderId)))
120	    .RequireAuthorization(OrderPermissions.IssueInvoices).WithTags("Invoices");
121	
122	app.MapGet("/api/orders/{orderId}/shipments", (string orderId, OrderService svc) =>
123	        Results.Ok(svc.ListShipments(orderId)))
124	    .RequireAuthorization(OrderPermissions.ViewShipments).WithTags("Shipments");
125	
126	app.MapPost("/api/orders/{orderId}/shipments/schedule", (string orderId, DateTimeOffset shipsAt, OrderService svc) =>
127	        Results.Ok(svc.ScheduleShipment(orderId, shipsAt)))
128	    .RequireAuthorization(OrderPermissions.ScheduleShipments).WithTags("Shipments");
129	
130	app.MapPost("/api/orders/{orderId}/refunds/approve", (string orderId, decimal amount, OrderService svc) =>
131	        Results.Ok(svc.ApproveRefund(orderId, amount)))
