187	    private sealed class FakeBusinessRoleStore : IBusinessRoleStore
188	    {
189	        private readonly Dictionary<string, BusinessRoleDto> _roles = new(StringComparer.Ordinal);
190	        public Task<BusinessRoleDto?> GetAsync(string name, CancellationToken ct) => Task.FromResult(_roles.TryGetValue(name, out var v) ? v : null);
191	        public Task<IReadOnlyCollection<BusinessRoleDto>> ListAsync(CancellationToken ct) => Task.FromResult((IReadOnlyCollection<BusinessRoleDto>)_roles.Values.ToArray());
192	        public Task<BusinessRoleDto> CreateAsync(string name, string? desc, IReadOnlyCollection<string> perms, CancellationToken ct)
193	        {
194	            if (_roles.ContainsKey(name)) throw new InvalidOperationException("exists");
195	            var dto = new BusinessRoleDto(name, desc, true, perms.ToArray());
196	            _roles[name] = dto; return Task.FromResult(dto);
197	        }
198	        public Task<BusinessRoleDto?> UpdateAsync(string name, string? desc, CancellationToken ct)
199	        {
200	            if (!_roles.TryGetValue(name, out var cur)) return Task.FromResult<BusinessRoleDto?>(null);
201	            var next = cur with { Description = desc }; _roles[name]=next; return Task.FromResult<BusinessRoleDto?>(next);
202	        }
203	        public Task<bool> DeleteAsync(string name, CancellationToken ct) => Task.FromResult(_roles.Remove(name));
204	        public Task<IReadOnlyCollection<string>> GetEffectivePermissionsAsync(string name, CancellationToken ct)
205	            => Task.FromResult(_roles.TryGetValue(name,out var r) ? r.Permissions : (IReadOnlyCollection<string>)Array.Empty<string>());
206	        public Task AddPermissionsAsync(string name, IReadOnlyCollection<string> perms, CancellationToken ct)
207	        {
208	            if (!_roles.TryGetValue(name, out var cur)) throw new KeyNotFoundException(name);
209	            _roles[name] = cur with { Permissions = cur.Permissions.Concat(perms).Distinct(StringComparer.Ordinal).ToArray() };
210	            return Task.CompletedTask;
211	        }
212	        public Task RemovePermissionAsync(string name, string perm, CancellationToken ct)
213	        {
214	            if (_roles.TryGetValue(name,out var cur)) _roles[name]=cur with{Permissions=cur.Permissions.Where(p=>p!=perm).ToArray()};
215	            return Task.CompletedTask;
216	        }
217	    }
