content.content:
1	using Company.Identity.Authentication.AspNetCore;
2	using Company.Identity.Authorization.AspNetCore;
3	using Identity.Api;
4	using Identity.Application;
5	using Identity.Contracts;
6	using Scalar.AspNetCore;
7	
8	var builder = WebApplication.CreateBuilder(args);
9	var authority = builder.Configuration["Identity:Authority"] ??
10	                throw new InvalidOperationException("Identity:Authority is required.");
11	var audience = builder.Configuration["Identity:Audience"] ?? string.Empty;
12	var requireHttpsMetadata = builder.Configuration["Identity:RequireHttpsMetadata"] ?? "false";
13	
14	builder.Services.AddSingleton(TimeProvider.System);
15	builder.Services.AddHttpContextAccessor();
16	builder.Services.AddHttpClient();
17	builder.Services.AddScoped<ICurrentUserContext, HttpCurrentUserContext>();
18	builder.Services.AddCompanyAuthentication(options =>
19	{
20	    options.Authority = authority;
21	    options.Audience = audience;
22	    options.RequireHttpsMetadata = bool.TryParse(requireHttpsMetadata, out var result) && result;
23	});
24	builder.Services.AddCompanyAuthorization();
25	builder.Services.AddGrpc();
26	
27	// Key management
28	builder.Services.Configure<KeyManagementOptions>(builder.Configuration.GetSection("Identity:KeyManagement"));
29	builder.Services.Configure<Identity.Infrastructure.Vault.VaultOptions>(
30	    builder.Configuration.GetSection("Identity:Vault"));
31	builder.Services.Configure<Identity.Infrastructure.Keycloak.KeycloakOptions>(
32	    builder.Configuration.GetSection("Identity:KeycloakAdmin"));
33	builder.Services.AddSingleton(sp =>
34	    sp.GetRequiredService<Microsoft.Extensions.Options.IOptions<KeyManagementOptions>>().Value);
35	builder.Services.AddSingleton<IKeyGenerationService, Identity.Infrastructure.RsaKeyGenerationService>();
36	builder.Services.AddScoped<IKeyRetirementSafety, Identity.Infrastructure.KeyRetirementSafety>();
37	builder.Services.AddSingleton<IKeyRotationLock, Identity.Infrastructure.Redis.InMemoryKeyRotationLock>();
38	builder.Services.AddSingleton<IAuditSink>(sp => new Identity.Infrastructure.NoopAuditSink());
39	builder.Services.AddHttpClient<Identity.Infrastructure.Vault.VaultSigningKeyStore>();
40	builder.Services.AddSingleton<ISigningKeyVault>(sp =>
41	    sp.GetRequiredService<Identity.Infrastructure.Vault.VaultSigningKeyStore>());
42	builder.Services.AddHttpClient<Identity.Infrastructure.Keycloak.KeycloakKeyManager>();
43	builder.Services.AddSingleton<IKeycloakKeyManager>(sp =>
44	    sp.GetRequiredService<Identity.Infrastructure.Keycloak.KeycloakKeyManager>());
45	
46	// Directory + permissions — Keycloak is source of truth; facade registry is in-memory so failure never blocks start.
47	builder.Services.AddHttpClient<Identity.Infrastructure.Keycloak.KeycloakDirectoryAdapter>();
48	builder.Services.AddSingleton<IUserDirectory>(sp =>
49	    sp.GetRequiredService<Identity.Infrastructure.Keycloak.KeycloakDirectoryAdapter>());
50	builder.Services.AddSingleton<IRoleDirectory>(sp =>
51	    sp.GetRequiredService<Identity.Infrastructure.Keycloak.KeycloakDirectoryAdapter>());
52	// Registered permissions are mirrored into Keycloak realm roles so they reach token claims
53	// through the existing oidc-usermodel-realm-role-mapper. Mirroring is best-effort and never
54	// blocks registration or startup.
55	builder.Services.AddHttpClient<Identity.Infrastructure.Keycloak.KeycloakRoleProvisioner>();
56	builder.Services.AddSingleton<IKeycloakRoleProvisioner>(sp =>
57	    sp.GetRequiredService<Identity.Infrastructure.Keycloak.KeycloakRoleProvisioner>());
58	builder.Services.AddSingleton<InMemoryPermissionRegistry>();
59	builder.Services.AddSingleton<IPermissionRegistry>(sp => new KeycloakSyncingPermissionRegistry(
60	    sp.GetRequiredService<InMemoryPermissionRegistry>(),
61	    sp.GetRequiredService<IKeycloakRoleProvisioner>(),
62	    sp.GetRequiredService<ILogger<KeycloakSyncingPermissionRegistry>>()));
63	builder.Services.AddSingleton<PermissionRegistrationService>();
64	
65	// Dynamic roles/scope infrastructure
66	builder.Services.AddMemoryCache();
67	builder.Services.ConfigureHttpJsonOptions(o => o.SerializerOptions.Converters.Add(new ScopeDictionaryConverter()));
68	builder.Services.Configure<Identity.Application.ScopedAccessOptions>(
69	    builder.Configuration.GetSection("Identity:ScopedAccess"));
70	builder.Services.AddSingleton<Identity.Application.IScopedAccessSerializer, Identity.Application.ScopedAccessSerializer>();
71	builder.Services.AddSingleton<Identity.Application.Scope.IScopeValueValidator, Identity.Application.Scope.DefaultScopeValueValidator>();
72	builder.Services.AddSingleton<Identity.Application.Scope.IScopeValueValidatorRegistry, Identity.Application.Scope.ScopeValueValidatorRegistry>();
73	builder.Services.AddSingleton<Identity.Application.Scope.ScopeAssignmentValidator>();
74	builder.Services.AddScoped<Identity.Application.Scope.IScopeDefinitionLookup, Identity.Persistence.KeyManagement.EfScopeDefinitionLookup>();
75	builder.Services.AddScoped<Identity.Persistence.KeyManagement.EfScopeDefinitionLookup>();
76	builder.Services.AddScoped<Identity.Application.Scope.IResourceScopeResolver, Identity.Persistence.KeyManagement.EfResourceScopeResolver>();
77	builder.Services.AddScoped<Identity.Application.Scope.IUserScopeReader, Identity.Persistence.KeyManagement.EfUserScopeStore>();
78	builder.Services.AddScoped<Identity.Application.Scope.IUserScopeWriter, Identity.Persistence.KeyManagement.EfUserScopeStore>();
79	builder.Services.AddScoped<Identity.Application.Scope.IScopeCacheInvalidator>(sp => sp.GetRequiredService<Identity.Persistence.KeyManagement.EfScopeDefinitionLookup>());
80	builder.Services.AddHttpClient<Identity.Infrastructure.Keycloak.KeycloakAdminTokenProvider>();
81	builder.Services.AddHttpClient<Identity.Infrastructure.Keycloak.KeycloakCompositeRoleStore>();
82	builder.Services.AddSingleton<Identity.Application.IBusinessRoleStore>(sp =>
83	    sp.GetRequiredService<Identity.Infrastructure.Keycloak.KeycloakCompositeRoleStore>());
84	builder.Services.AddHttpClient<Identity.Infrastructure.Keycloak.KeycloakScopedAccessStore>();
85	builder.Services.AddSingleton<Identity.Application.IScopedAccessStore>(sp =>
86	    sp.GetRequiredService<Identity.Infrastructure.Keycloak.KeycloakScopedAccessStore>());
87	builder.Services.AddHttpClient<Identity.Infrastructure.Keycloak.KeycloakUserProvisioner>();
88	builder.Services.AddSingleton<Identity.Application.IUserProvisioningService>(sp =>
89	    sp.GetRequiredService<Identity.Infrastructure.Keycloak.KeycloakUserProvisioner>());
90	builder.Services.AddHttpClient<Identity.Infrastructure.Keycloak.KeycloakUserRoleMapping>();
91	builder.Services.AddSingleton<Identity.Application.IUserRoleMapping>(sp =>
92	    sp.GetRequiredService<Identity.Infrastructure.Keycloak.KeycloakUserRoleMapping>());
93	builder.Services.AddScoped<Identity.Application.ProvisioningOrchestrator>(sp =>
94	    new Identity.Application.ProvisioningOrchestrator(
95	        sp.GetRequiredService<Identity.Application.IUserProvisioningService>(),
96	        sp.GetRequiredService<Identity.Application.IScopedAccessStore>(),
97	        sp.GetRequiredService<Identity.Application.IBusinessRoleStore>(),
98	        sp.GetRequiredService<Identity.Application.IUserRoleMapping>(),
99	        sp.GetRequiredService<Identity.Application.IPermissionRegistry>(),
100	        sp.GetRequiredService<Identity.Application.Scope.ScopeAssignmentValidator>(),
101	        sp.GetRequiredService<Identity.Application.Scope.IUserScopeWriter>()));
102	builder.Services.AddHttpClient<Identity.Infrastructure.Keycloak.KeycloakIamAccessClaimMapper>();
103	builder.Services.AddHttpClient<Identity.Infrastructure.Keycloak.FacadePermissionRegistrar>();
104	
105	
106	builder.Services.AddDbContext<Identity.Persistence.KeyManagement.KeyMetadataDbContext>((sp, o) =>
107	{
108	    var cfg = sp.GetRequiredService<IConfiguration>();
109	    var cs = cfg.GetConnectionString("KeyMetadata") ?? "Data Source=identity_keys.db";
110	    var provider = cfg["Identity:KeyMetadata:Provider"] ?? "sqlite";
111	    Identity.Persistence.KeyManagement.KeyMetadataDbContext.ConfigureProvider(o, provider, cs);
112	});
113	builder.Services.AddScoped<IKeyLifecycleRepository, Identity.Persistence.KeyManagement.EfKeyLifecycleRepository>();
114	builder.Services.AddScoped<KeyRotationService>();
115	builder.Services.AddHealthChecks();
116	
117	builder.Services.AddEndpointsApiExplorer();
118	builder.Services.AddOpenApi("v1", o =>
119	{
120	    o.AddDocumentTransformer((document, _, _) =>
121	    {
122	        document.Info.Title = "Identity Facade";
123	        document.Info.Description =
124	            "Keycloak-centric facade — auth proxy, directory, permissions, key lifecycle. " +
125	            "Present a Keycloak-issued JWT via the Bearer scheme below; privileged groups need the " +
126	            "matching Identity.* permission claims (e.g. Identity.Keys.Generate for key admin routes).";
