    private static string? Flush(List<string> buffer)
    {
        if (buffer.Count == 0) return null;
        var text = string.Join('\n', buffer).Trim();
        buffer.Clear();
        if (text.Length == 0) return null;
        return text.EndsWith(';') ? text[..^1].TrimEnd() : text;
    }
}

