/// <summary>
/// Model containing only the scope tables. Used solely to let EF emit provider-correct DDL
/// (identifier quoting, Guid/DateTimeOffset/bool mappings) for databases that already exist.
/// </summary>
public sealed class ScopeSchemaDbContext(DbContextOptions<ScopeSchemaDbContext> options) : DbContext(options)
{
    protected override void OnModelCreating(ModelBuilder b) => ScopeModelConfiguration.Configure(b);
}

/// <summary>
/// Creates the scope tables when they are missing.
/// <para>
/// The facade metadata DB is provisioned by <c>EnsureCreated</c>, which only ever creates a schema for
/// an <em>empty</em> database. An existing deployment (already holding the signing-key tables) therefore
/// never received the scope tables added by the dynamic-scope refactor, and every scope query failed
/// with a provider "table or view does not exist" error. This initializer closes that gap: EF generates
/// the provider-specific DDL from <see cref="ScopeSchemaDbContext"/> and each statement is executed
/// idempotently, so it is safe on a brand-new database (all statements no-op) and on a legacy one.
/// </para>
/// </summary>
public static class ScopeSchemaInitializer
{
    public static async Task EnsureAsync(KeyMetadataDbContext db, CancellationToken ct)
    {
        if (!db.Database.IsRelational()) return; // in-memory provider used by tests creates its own model
        var connectionString = db.Database.GetConnectionString();
        if (string.IsNullOrWhiteSpace(connectionString)) return;

        var options = new DbContextOptionsBuilder<ScopeSchemaDbContext>();
        ConfigureProvider(options, db.Database.ProviderName ?? "", connectionString);
        await using var schema = new ScopeSchemaDbContext(options.Options);

        var script = schema.Database.GenerateCreateScript();
        foreach (var statement in SqlScriptSplitter.Split(script))
        {
            try
            {
                // DDL comes from the EF model (never from user input); identifiers are quoted by EF itself.
                await schema.Database.ExecuteSqlRawAsync(statement, ct);
            }
            catch (Exception ex) when (IsAlreadyExists(ex))
            {
                // Table/index/constraint provisioned by an earlier run or by EnsureCreated — nothing to do.
            }
        }
    }

    private static void ConfigureProvider(DbContextOptionsBuilder b, string providerName, string connectionString)
    {
        if (providerName.Contains("Oracle", StringComparison.OrdinalIgnoreCase)) b.UseOracle(connectionString);
        else if (providerName.Contains("Npgsql", StringComparison.OrdinalIgnoreCase)) b.UseNpgsql(connectionString);
        else b.UseSqlite(connectionString);
    }

    private static bool IsAlreadyExists(Exception ex) => ex switch
    {
        // ORA-00955 name already used, ORA-01408 such column list already indexed,
        // ORA-02275 such referential constraint already exists, ORA-02260 table can have only one primary key.
        OracleException oracle => oracle.Number is 955 or 1408 or 2275 or 2260,
        PostgresException postgres => postgres.SqlState is "42P07" or "42710" or "42P16" or "42701",
        SqliteException sqlite => sqlite.SqliteErrorCode == 1 &&
                                  sqlite.Message.Contains("already exists", StringComparison.OrdinalIgnoreCase),
        _ => false
    };
}

/// <summary>
/// Splits a provider-generated DDL script into single statements. The scripts produced here contain only
/// plain CREATE TABLE / CREATE INDEX / ALTER TABLE ADD CONSTRAINT statements, so a statement ends at a
/// line ending in <c>;</c> or at a standalone batch terminator (<c>/</c>, Oracle).
/// </summary>
public static class SqlScriptSplitter
{
    public static IEnumerable<string> Split(string script)
    {
        var buffer = new List<string>();
        foreach (var raw in script.Split('\n'))
        {
            var line = raw.TrimEnd('\r');
            var trimmed = line.Trim();
            if (trimmed.Length == 0 || trimmed.StartsWith("--", StringComparison.Ordinal)) continue;
            if (trimmed == "/")
            {
                var batch = Flush(buffer);
                if (batch is not null) yield return batch;
                continue;
            }
            buffer.Add(line);
            if (trimmed.EndsWith(';'))
            {
                var statement = Flush(buffer);
                if (statement is not null) yield return statement;
            }
        }
        var trailing = Flush(buffer);
        if (trailing is not null) yield return trailing;
    }

    private static string? Flush(List<string> buffer)
    {
        if (buffer.Count == 0) return null;
        var text = string.Join('\n', buffer).Trim();
        buffer.Clear();
        if (text.Length == 0) return null;
        return text.EndsWith(';') ? text[..^1].TrimEnd() : text;
    }
}

