1	using System.Net.Http.Json;
2	using System.Text.Json;
3	using Identity.Application;
4	using Identity.Contracts;
5	using Microsoft.Extensions.Options;
6	
7	namespace Identity.Infrastructure.Keycloak;
8	
9	/// <summary>
10	/// Persists <see cref="ScopedAccessDocument"/> as a single namespaced user attribute
11	/// (<c>iam.scoped_access</c>). All other attributes are preserved via read-modify-write
12	/// against the full user representation (GET then PUT).
13	/// Application code never touches raw attribute dictionaries — the typed model is the boundary.
14	/// </summary>
15	public sealed class KeycloakScopedAccessStore(
16	    HttpClient http,
17	    IOptions<KeycloakOptions> opts,
18	    KeycloakAdminTokenProvider tokenProvider,
19	    IScopedAccessSerializer serializer) : IScopedAccessStore
20	{
21	    private readonly KeycloakOptions _o = opts.Value;
22	    private readonly ScopedAccessOptions _scopedOpts = new();
23	    private string AdminBase => $"{_o.BaseUrl.TrimEnd('/')}/admin/realms";
24	
25	    private string AttributeName => _scopedOpts.AttributeName ?? ScopedAccessConstants.AttributeName;
26	
27	    private async Task<JsonElement?> GetUserJsonAsync(string userId, string token, CancellationToken ct)
28	    {
29	        var req = new HttpRequestMessage(HttpMethod.Get, $"{AdminBase}/{_o.Realm}/users/{Uri.EscapeDataString(userId)}");
30	        req.Headers.Add("Authorization", $"Bearer {token}");
31	        try
32	        {
33	            var res = await http.SendAsync(req, ct);
34	            if (!res.IsSuccessStatusCode) return null;
35	            var doc = JsonDocument.Parse(await res.Content.ReadAsStringAsync(ct));
36	            return doc.RootElement.Clone();
37	        }
38	        catch { return null; }
39	    }
40	
41	    private async Task<bool> PutUserAsync(JsonElement userJson, string token, CancellationToken ct)
42	    {
43	        var userId = userJson.TryGetProperty("id", out var pid) ? pid.GetString() ?? "" : "";
44	        if (string.IsNullOrEmpty(userId)) return false;
45	        var json = userJson.GetRawText();
46	        var req = new HttpRequestMessage(HttpMethod.Put, $"{AdminBase}/{_o.Realm}/users/{Uri.EscapeDataString(userId)}")
47	        {
48	            Content = new StringContent(json, System.Text.Encoding.UTF8, "application/json")
49	        };
50	        req.Headers.Add("Authorization", $"Bearer {token}");
51	        try
52	        {
53	            var res = await http.SendAsync(req, ct);
54	            return res.IsSuccessStatusCode;
55	        }
56	        catch { return false; }
57	    }
58	
59	    private static string? ExtractAttribute(JsonElement userJson, string attributeName)
60	    {
61	        if (!userJson.TryGetProperty("attributes", out var attrs) || attrs.ValueKind != JsonValueKind.Object)
62	            return null;
63	        if (!attrs.TryGetProperty(attributeName, out var arr)) return null;
64	        if (arr.ValueKind == JsonValueKind.Array && arr.GetArrayLength() > 0)
65	            return arr[0].GetString();
66	        if (arr.ValueKind == JsonValueKind.String) return arr.GetString();
67	        return null;
68	    }
69	
70	    private static JsonElement SetAttribute(JsonElement userJson, string attributeName, string? value)
71	    {
72	        var doc = JsonDocument.Parse(userJson.GetRawText());
73	        var root = doc.RootElement;
74	        using var ms = new System.IO.MemoryStream();
75	        using var writer = new Utf8JsonWriter(ms);
76	        writer.WriteStartObject();
77	        foreach (var prop in root.EnumerateObject())
78	        {
79	            if (prop.NameEquals("attributes"))
80	            {
81	                writer.WritePropertyName("attributes");
82	                writer.WriteStartObject();
83	                var hasTarget = false;
84	                if (prop.Value.ValueKind == JsonValueKind.Object)
85	                {
86	                    foreach (var attr in prop.Value.EnumerateObject())
87	                    {
88	                        if (attr.NameEquals(attributeName))
89	                        {
90	                            hasTarget = true;
91	                            if (value is not null)
92	                            {
93	                                writer.WritePropertyName(attr.Name);
94	                                writer.WriteStartArray();
95	                                writer.WriteStringValue(value);
96	                                writer.WriteEndArray();
97	                            }
98	                            // if value is null, omit the attribute entirely (removal)
99	                        }
100	                        else
101	                        {
102	                            attr.WriteTo(writer);
103	                        }
104	                    }
105	                }
106	                if (!hasTarget && value is not null)
107	                {
108	                    writer.WritePropertyName(attributeName);
109	                    writer.WriteStartArray();
110	                    writer.WriteStringValue(value);
111	                    writer.WriteEndArray();
112	                }
113	                writer.WriteEndObject();
114	            }
115	            else
116	            {
117	                prop.WriteTo(writer);
118	            }
119	        }
120	        // If attributes didn't exist at all and we have a value, add it
121	        if (!root.TryGetProperty("attributes", out _) && value is not null)
122	        {
123	            // Already handled above by not having attributes prop; need to add
124	            // Re-parse: we already wrote without it, so we need to handle differently.
125	            // Simpler: close and re-build if needed. But our loop above already handled
126	            // the case where attributes missing — we didn't write it. So patch:
127	            // We need to re-open. Easiest: do a second pass if attributes missing.
128	        }
129	        writer.WriteEndObject();
130	        writer.Flush();
131	        var json = System.Text.Encoding.UTF8.GetString(ms.ToArray());
132	        // Handle missing attributes case: inject if needed
133	        if (!root.TryGetProperty("attributes", out _) && value is not null)
134	        {
135	            var parsed = JsonDocument.Parse(json);
136	            using var ms2 = new System.IO.MemoryStream();
137	            using var w2 = new Utf8JsonWriter(ms2);
138	            w2.WriteStartObject();
139	            foreach (var prop in parsed.RootElement.EnumerateObject()) prop.WriteTo(w2);
140	            w2.WritePropertyName("attributes");
141	            w2.WriteStartObject();
142	            w2.WritePropertyName(attributeName);
143	            w2.WriteStartArray();
144	            w2.WriteStringValue(value);
145	            w2.WriteEndArray();
146	            w2.WriteEndObject();
147	            w2.WriteEndObject();
148	            w2.Flush();
149	            json = System.Text.Encoding.UTF8.GetString(ms2.ToArray());
150	        }
151	        return JsonDocument.Parse(json).RootElement.Clone();
152	    }
153	
154	    public async Task<ScopedAccessDocument> GetAsync(string userId, CancellationToken ct)
155	    {
156	        var token = await tokenProvider.GetTokenAsync(ct);
157	        if (string.IsNullOrEmpty(token)) return ScopedAccessDocument.Empty;
158	        var userJson = await GetUserJsonAsync(userId, token, ct);
159	        if (userJson is null) return ScopedAccessDocument.Empty;
160	        var raw = ExtractAttribute(userJson.Value, AttributeName);
161	        return serializer.Deserialize(raw);
162	    }
163	
164	    public async Task SetAsync(string userId, ScopedAccessDocument document, CancellationToken ct)
165	    {
166	        var token = await tokenProvider.GetTokenAsync(ct);
167	        if (string.IsNullOrEmpty(token)) throw new InvalidOperationException("Keycloak admin token unavailable.");
168	        var userJson = await GetUserJsonAsync(userId, token, ct);
169	        if (userJson is null) throw new InvalidOperationException($"User '{userId}' not found.");
170	        string? value = document.Assignments.Count == 0 ? null : serializer.Serialize(document);
171	        var updated = SetAttribute(userJson.Value, AttributeName, value);
172	        var ok = await PutUserAsync(updated, token, ct);
173	        if (!ok) throw new InvalidOperationException($"Failed to update scoped access for user '{userId}'.");
174	    }
175	
176	    public async Task AddAssignmentAsync(string userId, ScopedRoleAssignmentDto assignment, CancellationToken ct)
177	    {
178	        ArgumentNullException.ThrowIfNull(assignment);
179	        ScopedAccessSerializer.Validate(assignment);
180	        var token = await tokenProvider.GetTokenAsync(ct);
181	        if (string.IsNullOrEmpty(token)) throw new InvalidOperationException("Keycloak admin token unavailable.");
182	        var userJson = await GetUserJsonAsync(userId, token, ct);
183	        if (userJson is null) throw new InvalidOperationException($"User '{userId}' not found.");
184	        var raw = ExtractAttribute(userJson.Value, AttributeName);
185	        var doc = serializer.Deserialize(raw);
186	        var normalized = NormalizeDto(assignment);
187	        // Merge: if role already exists, merge scopes; otherwise append
