70	/// <summary>
71	/// Model containing only the scope tables. Used solely to let EF emit provider-correct DDL
72	/// (identifier quoting, Guid/DateTimeOffset/bool mappings) for databases that already exist.
73	/// </summary>
74	public sealed class ScopeSchemaDbContext(DbContextOptions<ScopeSchemaDbContext> options) : DbContext(options)
75	{
76	    protected override void OnModelCreating(ModelBuilder b) => ScopeModelConfiguration.Configure(b);
77	}
78	
79	/// <summary>
80	/// Creates the scope tables when they are missing.
81	/// <para>
82	/// The facade metadata DB is provisioned by <c>EnsureCreated</c>, which only ever creates a schema for
83	/// an <em>empty</em> database. An existing deployment (already holding the signing-key tables) therefore
84	/// never received the scope tables added by the dynamic-scope refactor, and every scope query failed
85	/// with a provider "table or view does not exist" error. This initializer closes that gap: EF generates
86	/// the provider-specific DDL from <see cref="ScopeSchemaDbContext"/> and each statement is executed
87	/// idempotently, so it is safe on a brand-new database (all statements no-op) and on a legacy one.
88	/// </para>
89	/// </summary>
90	public static class ScopeSchemaInitializer
91	{
92	    public static async Task EnsureAsync(KeyMetadataDbContext db, CancellationToken ct)
93	    {
94	        if (!db.Database.IsRelational()) return; // in-memory provider used by tests creates its own model
95	        var connectionString = db.Database.GetConnectionString();
96	        if (string.IsNullOrWhiteSpace(connectionString)) return;
97	
98	        var options = new DbContextOptionsBuilder<ScopeSchemaDbContext>();
99	        ConfigureProvider(options, db.Database.ProviderName ?? "", connectionString);
100	        await using var schema = new ScopeSchemaDbContext(options.Options);
101	
102	        var script = schema.Database.GenerateCreateScript();
103	        foreach (var statement in SqlScriptSplitter.Split(script))
104	        {
105	            try
106	            {
107	                // DDL comes from the EF model (never from user input); identifiers are quoted by EF itself.
108	                await schema.Database.ExecuteSqlRawAsync(statement, ct);
109	            }
110	            catch (Exception ex) when (IsAlreadyExists(ex))
111	            {
112	                // Table/index/constraint provisioned by an earlier run or by EnsureCreated — nothing to do.
113	            }
114	        }
115	    }
116	
117	    private static void ConfigureProvider(DbContextOptionsBuilder b, string providerName, string connectionString)
118	    {
119	        if (providerName.Contains("Oracle", StringComparison.OrdinalIgnoreCase)) b.UseOracle(connectionString);
120	        else if (providerName.Contains("Npgsql", StringComparison.OrdinalIgnoreCase)) b.UseNpgsql(connectionString);
121	        else b.UseSqlite(connectionString);
122	    }
123	
124	    private static bool IsAlreadyExists(Exception ex) => ex switch
125	    {
126	        // ORA-00955 name already used, ORA-01408 such column list already indexed,
127	        // ORA-02275 such referential constraint already exists, ORA-02260 table can have only one primary key.
128	        OracleException oracle => oracle.Number is 955 or 1408 or 2275 or 2260,
129	        PostgresException postgres => postgres.SqlState is "42P07" or "42710" or "42P16" or "42701",
130	        SqliteException sqlite => sqlite.SqliteErrorCode == 1 &&
131	                                  sqlite.Message.Contains("already exists", StringComparison.OrdinalIgnoreCase),
132	        _ => false
133	    };
134	}
135	
136	/// <summary>
137	/// Splits a provider-generated DDL script into single statements. The scripts produced here contain only
138	/// plain CREATE TABLE / CREATE INDEX / ALTER TABLE ADD CONSTRAINT statements, so a statement ends at a
139	/// line ending in <c>;</c> or at a standalone batch terminator (<c>/</c>, Oracle).
140	/// </summary>
141	public static class SqlScriptSplitter
142	{
143	    public static IEnumerable<string> Split(string script)
144	    {
145	        var buffer = new List<string>();
