1	using System.Security.Claims;
2	using Identity.Contracts;
3	
4	namespace Company.Identity.Authorization;
5	
6	/// <summary>
7	/// Reusable access-context abstraction for microservices. Provides EF-Core-friendly primitives.
8	/// Centralizes parsing of the compact <c>iam_access</c> claim so business code never touches raw claim values.
9	/// </summary>
10	/// <remarks>
11	/// Permission checks and <see cref="GetScopeValues"/> may depend on the <c>iam_access</c> claim, which is
12	/// omitted from oversized tokens (see <see cref="ScopedAccessConstants.MaxInlineClaimBytes"/>). Callers that
13	/// may run against a token whose claim was dropped should <see cref="EnsureLoadedAsync"/> once per request to
14	/// lazily resolve the authoritative assignment set from the Identity Facade; when the claim is present the
15	/// call is a no-op and no HTTP round-trip happens.
16	/// </remarks>
17	public interface ICurrentAccessContext
18	{
19	    IReadOnlyCollection<ScopedRoleAssignment> GetAssignments();
20	    bool HasPermission(string permission);
21	    bool HasPermission(string permission, string scopeKey, string scopeValue);
22	    IReadOnlyCollection<string> GetScopeValues(string scopeKey);
23	    bool HasScope(string scopeKey, string scopeValue);
24	
25	    /// <summary>
26	    /// Resolves scoped assignments from the facade when they could not be read from the token claim.
27	    /// Idempotent; safe to call on every request. No-op when assignments came from the claim.
28	    /// </summary>
29	    Task EnsureLoadedAsync(CancellationToken ct = default);
30	}
31	
32	/// <summary>
33	/// Static, claims-only access context. Reads permissions from the standard <c>permission</c>/
34	/// <c>permissions</c>/role claims and scoped assignments from <c>iam_access</c>. Does not perform
35	/// facade resolution — <see cref="EnsureLoadedAsync"/> is a completed no-op. Used directly by unit
36	/// tests and as the building block behind <c>FacadeResolvingAccessContext</c>.
37	/// </summary>
38	public sealed class ClaimsPrincipalAccessContext : ICurrentAccessContext
39	{
40	    private readonly IReadOnlyCollection<string> _permissions;
41	    private readonly IReadOnlyCollection<ScopedRoleAssignment> _assignments;
42	    private readonly IReadOnlyDictionary<string, HashSet<string>> _scopeIndex;
43	
44	    public ClaimsPrincipalAccessContext(ClaimsPrincipal principal)
45	    {
46	        _permissions = principal.FindAll("permission")
47	            .Concat(principal.FindAll("permissions"))
48	            .Select(c => c.Value)
49	            .Distinct(StringComparer.Ordinal)
50	            .ToArray();
51	        // Also include role claims as permissions for compatibility
52	        var roles = principal.FindAll(ClaimTypes.Role).Concat(principal.FindAll("role")).Select(c => c.Value);
53	        _permissions = _permissions.Concat(roles).Distinct(StringComparer.Ordinal).ToArray();
54	
55	        _assignments = ParseAssignments(principal);
56	        _scopeIndex = BuildScopeIndex(_assignments);
57	    }
58	
59	    // Internal ctor used by FacadeResolvingAccessContext after a facade round-trip.
60	    internal ClaimsPrincipalAccessContext(
61	        IReadOnlyCollection<string> permissions,
62	        IReadOnlyCollection<ScopedRoleAssignment> assignments)
63	    {
64	        _permissions = permissions;
65	        _assignments = assignments;
66	        _scopeIndex = BuildScopeIndex(assignments);
67	    }
68	
69	    /// <summary>True when the assignments were carried by the token claim (no facade resolution needed).</summary>
70	    internal bool HasInlineAssignments => _assignments.Count > 0;
71	
72	    internal IReadOnlyCollection<string> Permissions => _permissions;
73	
74	    public IReadOnlyCollection<ScopedRoleAssignment> GetAssignments() => _assignments;
75	
76	    public bool HasPermission(string permission)
77	        => _permissions.Contains(permission, StringComparer.Ordinal);
78	
79	    public bool HasPermission(string permission, string scopeKey, string scopeValue)
80	    {
81	        if (!HasPermission(permission)) return false;
82	        return HasScope(scopeKey, scopeValue);
83	    }
84	
85	    public IReadOnlyCollection<string> GetScopeValues(string scopeKey)
86	        => _scopeIndex.TryGetValue(scopeKey, out var set)
87	            ? set.ToArray()
88	            : Array.Empty<string>();
89	
90	    public bool HasScope(string scopeKey, string scopeValue)
91	        => _scopeIndex.TryGetValue(scopeKey, out var set) && set.Contains(scopeValue);
92	
93	    // Static context never resolves from the facade; the claims are all there is.
94	    public Task EnsureLoadedAsync(CancellationToken ct = default) => Task.CompletedTask;
95	
96	    private static IReadOnlyDictionary<string, HashSet<string>> BuildScopeIndex(
97	        IReadOnlyCollection<ScopedRoleAssignment> assignments)
98	    {
99	        var index = new Dictionary<string, HashSet<string>>(StringComparer.Ordinal);
100	        foreach (var a in assignments)
101	        foreach (var kv in a.Scopes)
102	        {
103	            if (!index.TryGetValue(kv.Key, out var set))
104	            {
105	                set = new HashSet<string>(StringComparer.Ordinal);
106	                index[kv.Key] = set;
107	            }
108	            foreach (var v in kv.Value) set.Add(v);
109	        }
110	        return index;
111	    }
112	
113	    private static IReadOnlyCollection<ScopedRoleAssignment> ParseAssignments(ClaimsPrincipal principal)
114	    {
115	        var claimValues = principal.FindAll(ScopedAccessConstants.ClaimName).Select(c => c.Value).ToArray();
116	        if (claimValues.Length == 0) return Array.Empty<ScopedRoleAssignment>();
117	
118	        // The claim may be a single JSON array string or multiple string claims.
119	        // Try single-value JSON array first.
120	        var combined = claimValues.Length == 1 ? claimValues[0] : string.Join("", claimValues);
121	        if (string.IsNullOrWhiteSpace(combined)) return Array.Empty<ScopedRoleAssignment>();
122	
123	        try
124	        {
125	            var doc = System.Text.Json.JsonDocument.Parse(combined);
126	            if (doc.RootElement.ValueKind == System.Text.Json.JsonValueKind.Array)
127	            {
128	                return System.Text.Json.JsonSerializer.Deserialize<ScopedRoleAssignment[]>(
129	                    combined,
130	                    new System.Text.Json.JsonSerializerOptions { PropertyNamingPolicy = System.Text.Json.JsonNamingPolicy.CamelCase })
131	                    ?.Where(a => !string.IsNullOrWhiteSpace(a.Role))
132	                    .Select(a => new ScopedRoleAssignment(
133	                        a.Role.Trim(),
134	                        NormalizeScopes(a.Scopes)))
135	                    .ToArray() ?? Array.Empty<ScopedRoleAssignment>();
136	            }
137	        }
138	        catch { }
139	
140	        return Array.Empty<ScopedRoleAssignment>();
141	    }
142	
143	    private static IReadOnlyDictionary<string, IReadOnlyCollection<string>> NormalizeScopes(
144	        IReadOnlyDictionary<string, IReadOnlyCollection<string>>? scopes)
145	    {
146	        if (scopes is null || scopes.Count == 0)
147	            return new Dictionary<string, IReadOnlyCollection<string>>(StringComparer.Ordinal);
148	        var result = new Dictionary<string, IReadOnlyCollection<string>>(StringComparer.Ordinal);
149	        foreach (var kv in scopes)
150	        {
151	            var key = kv.Key?.Trim();
152	            if (string.IsNullOrWhiteSpace(key)) continue;
153	            var values = kv.Value?.Where(v => !string.IsNullOrWhiteSpace(v))
154	                .Select(v => v.Trim())
155	                .Distinct(StringComparer.Ordinal)
156	                .ToArray() ?? Array.Empty<string>();
157	            if (values.Length == 0) continue;
158	            result[key!] = values;
159	        }
160	        return result;
161	    }
162	}
