1	using System.Net;
2	using System.Net.Http.Json;
3	using System.Text.Json;
4	using Identity.Application;
5	using Microsoft.Extensions.Logging;
6	using Microsoft.Extensions.Options;
7	
8	namespace Identity.Infrastructure.Keycloak;
9	
10	/// <summary>
11	/// Creates Keycloak realm roles for registered permissions via the Admin REST API.
12	/// Uses the same admin-token bootstrap as <see cref="KeycloakDirectoryAdapter"/>.
13	/// Never throws — all failures are logged and swallowed so that role provisioning
14	/// never blocks permission registration or application startup.
15	/// </summary>
16	public sealed class KeycloakRoleProvisioner(
17	    HttpClient http,
18	    IOptions<KeycloakOptions> opts,
19	    ILogger<KeycloakRoleProvisioner> logger) : IKeycloakRoleProvisioner
20	{
21	    private readonly KeycloakOptions _o = opts.Value;
22	    private string AdminBase => $"{_o.BaseUrl.TrimEnd('/')}/admin/realms";
23	
24	    private async Task<string> GetAdminTokenAsync(CancellationToken ct)
25	    {
26	        if (!string.IsNullOrEmpty(_o.AdminClientSecret))
27	        {
28	            var form = new FormUrlEncodedContent(new Dictionary<string, string>
29	            {
30	                ["grant_type"] = "client_credentials",
31	                ["client_id"] = _o.AdminClientId,
32	                ["client_secret"] = _o.AdminClientSecret,
33	            });
34	            try
35	            {
36	                var res = await http.PostAsync(
37	                    $"{_o.BaseUrl.TrimEnd('/')}/realms/master/protocol/openid-connect/token", form, ct);
38	                if (!res.IsSuccessStatusCode) return string.Empty;
39	                var doc = JsonDocument.Parse(await res.Content.ReadAsStringAsync(ct));
40	                return doc.RootElement.TryGetProperty("access_token", out var t)
41	                    ? t.GetString() ?? string.Empty
42	                    : string.Empty;
43	            }
44	            catch
45	            {
46	                return string.Empty;
47	            }
48	        }
49	
50	        if (!string.IsNullOrEmpty(_o.AdminUsername) && !string.IsNullOrEmpty(_o.AdminPassword))
51	        {
52	            var form = new FormUrlEncodedContent(new Dictionary<string, string>
53	            {
54	                ["grant_type"] = "password",
55	                ["client_id"] = _o.AdminClientId,
56	                ["username"] = _o.AdminUsername,
57	                ["password"] = _o.AdminPassword,
58	            });
59	            try
60	            {
61	                var res = await http.PostAsync(
62	                    $"{_o.BaseUrl.TrimEnd('/')}/realms/master/protocol/openid-connect/token", form, ct);
63	                if (!res.IsSuccessStatusCode) return string.Empty;
64	                var doc = JsonDocument.Parse(await res.Content.ReadAsStringAsync(ct));
65	                return doc.RootElement.TryGetProperty("access_token", out var t)
66	                    ? t.GetString() ?? string.Empty
67	                    : string.Empty;
68	            }
69	            catch
70	            {
71	                return string.Empty;
72	            }
73	        }
74	
75	        return string.Empty;
76	    }
77	
78	    public async Task<bool> EnsureRoleAsync(string name, string? description, CancellationToken ct)
79	    {
80	        if (string.IsNullOrWhiteSpace(name)) return false;
81	
82	        var token = await GetAdminTokenAsync(ct);
83	        if (string.IsNullOrEmpty(token))
84	        {
85	            logger.LogWarning("Cannot provision Keycloak role {RoleName}: admin token unavailable", name);
86	            return false;
87	        }
88	
89	        // Check if the role already exists — GET returns 200 + role body.
90	        try
91	        {
92	            var getReq = new HttpRequestMessage(HttpMethod.Get,
93	                $"{AdminBase}/{_o.Realm}/roles/{Uri.EscapeDataString(name)}");
94	            getReq.Headers.Add("Authorization", $"Bearer {token}");
95	            var getRes = await http.SendAsync(getReq, ct);
96	            if (getRes.IsSuccessStatusCode)
97	            {
98	                // Role already exists — nothing to do.
99	                return true;
100	            }
101	        }
102	        catch (Exception ex)
103	        {
104	            logger.LogDebug(ex, "Error checking role {RoleName} existence", name);
105	        }
106	
107	        // Create the role.
108	        try
109	        {
110	            var body = new { name, description = description ?? $"Permission: {name}" };
111	            var postReq = new HttpRequestMessage(HttpMethod.Post, $"{AdminBase}/{_o.Realm}/roles")
112	            {
113	                Content = JsonContent.Create(body)
114	            };
115	            postReq.Headers.Add("Authorization", $"Bearer {token}");
116	            var postRes = await http.SendAsync(postReq, ct);
117	            if (postRes.IsSuccessStatusCode || postRes.StatusCode == HttpStatusCode.Conflict)
118	            {
119	                logger.LogDebug("Keycloak role {RoleName} provisioned (status {Status})", name, postRes.StatusCode);
120	                return true;
121	            }
122	
123	            logger.LogWarning("Failed to provision Keycloak role {RoleName}: HTTP {Status}", name, postRes.StatusCode);
124	            return false;
125	        }
126	        catch (Exception ex)
127	        {
128	            logger.LogWarning(ex, "Failed to provision Keycloak role {RoleName}", name);
129	            return false;
130	        }
131	    }
132	}

