1	using Identity.Application.Scope;
2	using Identity.Contracts;
3	
4	namespace Identity.Application;
5	
6	public sealed class ProvisioningOrchestrator(
7	    IUserProvisioningService users,
8	    IScopedAccessStore scopedStore,
9	    IBusinessRoleStore roles,
10	    IUserRoleMapping roleMapping,
11	    IPermissionRegistry permissionRegistry,
12	    ScopeAssignmentValidator? scopeValidator = null,
13	    IUserScopeWriter? userScopeWriter = null)
14	{
15	    public async Task<(UserDto User, ScopedAccessDocument Scoped)> CreateUserWithAssignmentsAsync(
16	        CreateUserRequest request, CancellationToken ct)
17	    {
18	        ArgumentNullException.ThrowIfNull(request);
19	        if (request.Assignments is not null)
20	        {
21	            foreach (var a in request.Assignments) ScopedAccessSerializer.Validate(a);
22	            if (scopeValidator is not null)
23	            {
24	                var errors = await scopeValidator.ValidateAsync(request.Assignments, roles, ct);
25	                if (errors.Count > 0) throw new Scope.ScopedValidationException(errors);
26	            }
27	            else
28	            {
29	                foreach (var a in request.Assignments)
30	                {
31	                    var role = await roles.GetAsync(a.Role, ct);
32	                    if (role is null) throw new InvalidOperationException($"Role '{a.Role}' does not exist.");
33	                }
34	            }
35	        }
36	        UserDto created;
37	        try { created = await users.CreateUserAsync(request, ct); }
38	        catch (Exception ex) { throw new InvalidOperationException($"Failed to create user '{request.Username}': {ex.Message}", ex); }
39	        if (request.Assignments is null || request.Assignments.Count == 0) return (created, ScopedAccessDocument.Empty);
40	        try
41	        {
42	            var doc = ToDocument(request.Assignments);
43	            await scopedStore.SetAsync(created.Id, doc, ct);
44	            if (userScopeWriter is not null) await userScopeWriter.SetAsync(created.Id, request.Assignments, ct);
45	            foreach (var a in request.Assignments) await SafeMapRoleAsync(created.Id, a.Role, ct);
46	            return (created, doc);
47	        }
48	        catch (Scope.ScopedValidationException) { try { await users.DeleteUserAsync(created.Id, ct); } catch { } throw; }
49	        catch (Exception ex)
50	        {
51	            try { await users.DeleteUserAsync(created.Id, ct); } catch { }
52	            throw new InvalidOperationException($"User '{request.Username}' was not created because scoped assignment failed: {ex.Message}", ex);
53	        }
54	    }
55	
56	    public async Task<ScopedAccessDocument> AddScopedAssignmentAsync(string userId, ScopedRoleAssignmentDto assignment, CancellationToken ct)
57	    {
58	        ScopedAccessSerializer.Validate(assignment);
59	        if (scopeValidator is not null)
60	        {
61	            var errors = await scopeValidator.ValidateAsync(new[] { assignment }, roles, ct);
62	            if (errors.Count > 0) throw new Scope.ScopedValidationException(errors);
63	        }
64	        else
65	        {
66	            var role = await roles.GetAsync(assignment.Role, ct);
67	            if (role is null) throw new InvalidOperationException($"Role '{assignment.Role}' does not exist.");
68	        }
69	        await scopedStore.AddAssignmentAsync(userId, assignment, ct);
70	        if (userScopeWriter is not null)
71	        {
72	            var current = await scopedStore.GetAsync(userId, ct);
73	            var dtos = current.Assignments.Select(a => new ScopedRoleAssignmentDto(a.Role, a.Scopes)).ToArray();
74	            await userScopeWriter.SetAsync(userId, dtos, ct);
75	        }
76	        await SafeMapRoleAsync(userId, assignment.Role, ct);
77	        return await scopedStore.GetAsync(userId, ct);
78	    }
79	
80	    public async Task<ScopedAccessDocument> ReplaceAssignmentsAsync(string userId, IReadOnlyCollection<ScopedRoleAssignmentDto> assignments, CancellationToken ct)
81	    {
82	        foreach (var a in assignments) ScopedAccessSerializer.Validate(a);
83	        if (scopeValidator is not null)
84	        {
85	            var errors = await scopeValidator.ValidateAsync(assignments, roles, ct);
86	            if (errors.Count > 0) throw new Scope.ScopedValidationException(errors);
87	        }
88	        else
89	        {
90	            foreach (var a in assignments)
91	            {
92	                var role = await roles.GetAsync(a.Role, ct);
93	                if (role is null) throw new InvalidOperationException($"Role '{a.Role}' does not exist.");
94	            }
95	        }
96	        var previous = await scopedStore.GetAsync(userId, ct);
97	        var previousRoles = previous.Assignments.Select(a => a.Role).ToHashSet(StringComparer.Ordinal);
98	        var nextRoles = assignments.Select(a => a.Role.Trim()).ToHashSet(StringComparer.Ordinal);
99	        var doc = ToDocument(assignments);
100	        await scopedStore.SetAsync(userId, doc, ct);
101	        if (userScopeWriter is not null) await userScopeWriter.SetAsync(userId, assignments, ct);
102	        foreach (var r in nextRoles.Except(previousRoles, StringComparer.Ordinal)) await SafeMapRoleAsync(userId, r, ct);
103	        foreach (var r in previousRoles.Except(nextRoles, StringComparer.Ordinal)) await SafeUnmapRoleAsync(userId, r, ct);
104	        return doc;
105	    }
106	
107	    public async Task RemoveScopedAssignmentAsync(string userId, string role, CancellationToken ct)
108	    {
109	        await scopedStore.RemoveAssignmentAsync(userId, role, ct);
110	        if (userScopeWriter is not null)
111	        {
112	            var remaining = await scopedStore.GetAsync(userId, ct);
113	            var dtos = remaining.Assignments.Select(a => new ScopedRoleAssignmentDto(a.Role, a.Scopes)).ToArray();
114	            await userScopeWriter.SetAsync(userId, dtos, ct);
115	        }
116	        var still = await scopedStore.GetAsync(userId, ct);
117	        if (!still.Assignments.Any(a => string.Equals(a.Role, role, StringComparison.Ordinal)))
118	            await SafeUnmapRoleAsync(userId, role, ct);
119	    }
120	
121	    public async Task<bool> DeleteBusinessRoleSafeAsync(string roleName, CancellationToken ct)
122	    {
123	        var usersWithRole = await roleMapping.GetUsersWithRealmRoleAsync(roleName, ct);
124	        if (usersWithRole.Count > 0) throw new InvalidOperationException($"Cannot delete business role '{roleName}': still assigned to {usersWithRole.Count} user(s). Remove scoped assignments first.");
125	        return await roles.DeleteAsync(roleName, ct);
126	    }
127	
