40	/// <summary>
41	/// Holder for a private PEM whose lifetime is the single call that hands it to Vault and/or Keycloak.
42	/// Implementations must zero memory on <see cref="IDisposable.Dispose"/>.
43	/// </summary>
44	public sealed class TransientPrivatePem : IDisposable
45	{
46	    private string? _pem;
47	    private bool _disposed;
48	
49	    public TransientPrivatePem(string pem) => _pem = pem ?? throw new ArgumentNullException(nameof(pem));
50	
51	    public string Pem => _disposed || _pem is null
52	        ? throw new ObjectDisposedException(nameof(TransientPrivatePem))
53	        : _pem;
54	
55	    public void Dispose()
56	    {
57	        if (_disposed) return;
58	        _disposed = true;
59	        if (_pem is not null)
60	        {
61	            // Overwrite the managed string's characters where possible (best-effort in .NET).
62	            // Callers must also avoid keeping additional copies.
63	            _pem = new string('\0', _pem.Length);
64	            _pem = null;
65	        }
66	
67	        GC.SuppressFinalize(this);
68	    }
69	
70	    public override string ToString() => "private:***";
71	}
