11	var audience = builder.Configuration["Identity:Audience"] ?? string.Empty;
12	var requireHttpsMetadata = builder.Configuration["Identity:RequireHttpsMetadata"] ?? "false";
13	
14	builder.Services.AddSingleton(TimeProvider.System);
15	builder.Services.AddHttpContextAccessor();
