        {
            name = ScopeName,
            description = "Exposes iam.scoped_access as iam_access claim",
            protocol = "openid-connect",
            attributes = new Dictionary<string, string>
            {
                ["include.in.token.scope"] = "false",
                ["display.on.consent.screen"] = "false",
                ["gui.order"] = "",
            }
        };
