        var uj = await GetUserJsonAsync(userId, token, ct);
        if (uj is null) return ScopedAccessDocument.Empty;
        // Try new namespaced attrs first
        var scopeAttrs = ExtractScopeAttrs(uj.Value);
        if (scopeAttrs.Count > 0)
        {
            // Each distinct role is unknown here — we return a single synthetic assignment per role derived from groups
            // Simpler: expose as one assignment per group with its scopes, or merge? Keep compat with AccessContext: return per-role assignments
            var groups = await GetUserGroupsAsync(userId, token, ct);
            var byRole = new List<ScopedRoleAssignment>();
            foreach (var g in groups)
            {
                // For each group, fetch its scopes and intersect with user's scopes? Instead union: if user has value for key, include for that role
                // Minimal: one assignment per group with whatever user-level scopes exist
                var dict = scopeAttrs.ToDictionary(k=>k.Key, v=>(IReadOnlyCollection<string>)v.Value, StringComparer.Ordinal);
                if (dict.Count>0) byRole.Add(new ScopedRoleAssignment(g, dict));
            }
            if (byRole.Count==0) // user not in any group but has scopes — single anonymous assignment
                byRole.Add(new ScopedRoleAssignment("_user", scopeAttrs.ToDictionary(k=>k.Key, v=>(IReadOnlyCollection<string>)v.Value, StringComparer.Ordinal)));
