using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;

namespace Identity.Infrastructure.Keycloak;

/// <summary>
/// Hardens the Keycloak Declarative User Profile so that <c>authz.scope.*</c>
/// (and the legacy <c>iam.scoped_access</c>) are admin-only writable.
/// Users cannot self-grant scopes via Account API / User Profile endpoints.
/// Complements server-side validation — defense in depth.
/// Best-effort; never blocks startup.
/// </summary>
public sealed class KeycloakUserProfileHardening(
    HttpClient http,
    IOptions<KeycloakOptions> opts,
    KeycloakAdminTokenProvider tokenProvider,
    ILogger<KeycloakUserProfileHardening> logger)
{
    private readonly KeycloakOptions _o = opts.Value;
    private string AdminBase => $"{_o.BaseUrl.TrimEnd('/')}/admin/realms";

    public async Task EnsureAsync(CancellationToken ct)
    {
        var token = await tokenProvider.GetTokenAsync(ct);
        if (string.IsNullOrEmpty(token)) { logger.LogDebug("Skipping User Profile hardening — token unavailable"); return; }
        try
        {
            var getReq = new HttpRequestMessage(HttpMethod.Get, $"{AdminBase}/{_o.Realm}/users/profile");
            getReq.Headers.Add("Authorization", $"Bearer {token}");
            var getRes = await http.SendAsync(getReq, ct);
            if (!getRes.IsSuccessStatusCode) { logger.LogDebug("User Profile GET failed: {Status}", getRes.StatusCode); return; }
            var json = await getRes.Content.ReadAsStringAsync(ct);
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            // Build patched profile: ensure attributes for authz.scope.* wildcard and legacy iam.scoped_access are admin-only edit.
            // Keycloak UP uses per-attribute permissions: {"view":["admin","user"],"edit":["admin"]}
            // We inject/override two unmanaged attribute configs mixing with existing.
            var patched = PatchProfile(root);
            if (patched is null) return; // already hardened

            var putReq = new HttpRequestMessage(HttpMethod.Put, $"{AdminBase}/{_o.Realm}/users/profile")
            { Content = JsonContent.Create(JsonDocument.Parse(patched).RootElement) };
            putReq.Headers.Add("Authorization", $"Bearer {token}");
            var putRes = await http.SendAsync(putReq, ct);
            if (!putRes.IsSuccessStatusCode)
                logger.LogDebug("User Profile PUT failed: {Status} {Body}", putRes.StatusCode, await putRes.Content.ReadAsStringAsync(ct));
            else
                logger.LogInformation("Hardened User Profile: authz.scope.* admin-only");
        }
        catch (Exception ex) { logger.LogDebug(ex, "User Profile hardening failed"); }
    }

    private static string? PatchProfile(JsonElement root)
    {
        // Check if already has attributes for our keys with edit: admin-only
        var hasHardening = false;
        if (root.TryGetProperty("attributes", out var attrs) && attrs.ValueKind == JsonValueKind.Array)
        {
            foreach (var a in attrs.EnumerateArray())
            {
                var name = a.TryGetProperty("name", out var n) ? n.GetString() : null;
                if (name is "authz.scope.*" or "iam.scoped_access")
                {
                    if (a.TryGetProperty("permissions", out var perms) &&
                        perms.TryGetProperty("edit", out var edit) && edit.ValueKind == JsonValueKind.Array)
                    {
                        var editors = edit.EnumerateArray().Select(e => e.GetString()).ToHashSet(StringComparer.Ordinal);
                        if (editors.SetEquals(new[] { "admin" })) hasHardening = true;
                    }
                }
            }
            if (hasHardening) return null; // already present — avoid churn
        }

        // Build new profile JSON by cloning and injecting attributes if missing
        using var ms = new System.IO.MemoryStream();
        using var w = new Utf8JsonWriter(ms);
        w.WriteStartObject();
        bool wroteAttrs = false;
        foreach (var prop in root.EnumerateObject())
        {
            if (prop.NameEquals("attributes") && prop.Value.ValueKind == JsonValueKind.Array)
            {
                w.WritePropertyName("attributes");
                w.WriteStartArray();
                foreach (var a in prop.Value.EnumerateArray()) a.WriteTo(w);
                // Ensure authz.scope.* wildcard
                if (!ContainsAttr(prop.Value, "authz.scope.*"))
                {
                    w.WriteStartObject();
                    w.WriteString("name", "authz.scope.*");
                    w.WriteString("displayName", "${authz.scope.*}");
                    w.WritePropertyName("permissions"); w.WriteStartObject();
                    w.WritePropertyName("view"); w.WriteStartArray(); w.WriteStringValue("admin"); w.WriteEndArray();
                    w.WritePropertyName("edit"); w.WriteStartArray(); w.WriteStringValue("admin"); w.WriteEndArray();
                    w.WriteEndObject();
                    w.WritePropertyName("validations"); w.WriteStartObject(); w.WriteEndObject();
                    w.WritePropertyName("annotations"); w.WriteStartObject(); w.WriteEndObject();
                    w.WriteEndObject();
                }
                if (!ContainsAttr(prop.Value, "iam.scoped_access"))
                {
                    w.WriteStartObject();
                    w.WriteString("name", "iam.scoped_access");
                    w.WriteString("displayName", "${iam.scoped_access}");
                    w.WritePropertyName("permissions"); w.WriteStartObject();
                    w.WritePropertyName("view"); w.WriteStartArray(); w.WriteStringValue("admin"); w.WriteEndArray();
                    w.WritePropertyName("edit"); w.WriteStartArray(); w.WriteStringValue("admin"); w.WriteEndArray();
                    w.WriteEndObject();
                    w.WritePropertyName("validations"); w.WriteStartObject(); w.WriteEndObject();
                    w.WritePropertyName("annotations"); w.WriteStartObject(); w.WriteEndObject();
                    w.WriteEndObject();
                }
                w.WriteEndArray();
                wroteAttrs = true;
            }
            else prop.WriteTo(w);
        }
        if (!wroteAttrs)
        {
            w.WritePropertyName("attributes");
            w.WriteStartArray();
            w.WriteStartObject();
            w.WriteString("name", "authz.scope.*");
            w.WritePropertyName("permissions"); w.WriteStartObject();
            w.WritePropertyName("view"); w.WriteStartArray(); w.WriteStringValue("admin"); w.WriteEndArray();
            w.WritePropertyName("edit"); w.WriteStartArray(); w.WriteStringValue("admin"); w.WriteEndArray();
            w.WriteEndObject();
            w.WriteEndArray();
        }
        w.WriteEndObject();
        w.Flush();
        return System.Text.Encoding.UTF8.GetString(ms.ToArray());
    }

    private static bool ContainsAttr(JsonElement arr, string name)
    {
        foreach (var a in arr.EnumerateArray())
            if (a.TryGetProperty("name", out var n) && n.GetString() == name) return true;
        return false;
    }
}

using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;

namespace Identity.Infrastructure.Keycloak;

/// <summary>
/// Provisions the <c>authz-scopes</c> client scope that exposes <c>authz.scope.*</c>
/// user/group attributes as token claims. One <c>oidc-usermodel-attribute-mapper</c>
/// per scope key → claim <c>scope.&lt;key&gt;</c> (flat, multivalued) plus a
/// JSON <c>scopes</c> claim for convenience. Stacked built-in mappers are sufficient;
/// no custom SPI is required for the nested JSON — consumers can reconstruct
/// <c>scopes:{region:[…]}</c> from the flat claims, or read the single
/// <c>iam_access</c> JSON claim during the migration window.
/// Freshness: already-issued access tokens do NOT mutate; short-lived AT (300s for
/// identity-facade) + refresh-token rotation propagates changes on next refresh.
/// Best-effort, never blocks startup.
/// </summary>
public sealed class KeycloakScopeClaimMapper(
    HttpClient http,
    IOptions<KeycloakOptions> opts,
    KeycloakAdminTokenProvider tokenProvider,
    ILogger<KeycloakScopeClaimMapper> logger)
{
    private readonly KeycloakOptions _o = opts.Value;
    private string AdminBase => $"{_o.BaseUrl.TrimEnd('/')}/admin/realms";
    private const string ScopeName = "authz-scopes";
    private const string ScopeAttrPrefix = "authz.scope.";

    public async Task EnsureAsync(CancellationToken ct)
    {
        var token = await tokenProvider.GetTokenAsync(ct);
        if (string.IsNullOrEmpty(token)) { logger.LogDebug("Skipping authz-scopes mapper — token unavailable"); return; }
        try
        {
            var scopeId = await EnsureClientScopeAsync(token, ct);
            if (string.IsNullOrEmpty(scopeId)) return;
            await EnsureDefaultScopeAsync(scopeId, token, ct);
            // Ensure mappers for registry-defined scopes plus well-known defaults (so startup works before registry exists)
            var keys = await ResolveScopeKeysAsync(token, ct);
            foreach (var k in keys) await EnsureAttributeMapperAsync(scopeId, k, token, ct);
        }
        catch (Exception ex) { logger.LogDebug(ex, "Failed to provision authz-scopes mappers"); }
    }

    private async Task<string> EnsureClientScopeAsync(string token, CancellationToken ct)
    {
        var listReq = new HttpRequestMessage(HttpMethod.Get, $"{AdminBase}/{_o.Realm}/client-scopes");
        listReq.Headers.Add("Authorization", $"Bearer {token}");
        var listRes = await http.SendAsync(listReq, ct);
        if (listRes.IsSuccessStatusCode)
        {
            var doc = JsonDocument.Parse(await listRes.Content.ReadAsStringAsync(ct));
            if (doc.RootElement.ValueKind == JsonValueKind.Array)
                foreach (var el in doc.RootElement.EnumerateArray())
                    if (el.TryGetProperty("name", out var n) && n.GetString() == ScopeName && el.TryGetProperty("id", out var id))
                        return id.GetString() ?? "";
        }
        var body = new { name = ScopeName, description = "Exposes authz.scope.* attributes as scopes claims", protocol = "openid-connect", attributes = new Dictionary<string,string>{ ["include.in.token.scope"]="false", ["display.on.consent.screen"]="false" } };
        var createReq = new HttpRequestMessage(HttpMethod.Post, $"{AdminBase}/{_o.Realm}/client-scopes") { Content = JsonContent.Create(body) };
        createReq.Headers.Add("Authorization", $"Bearer {token}");
        var createRes = await http.SendAsync(createReq, ct);
        if (createRes.Headers.Location is not null) return createRes.Headers.Location.ToString().Split('/').LastOrDefault()?.Trim() ?? "";
        if (createRes.StatusCode == System.Net.HttpStatusCode.Conflict)
        {
            var retry = new HttpRequestMessage(HttpMethod.Get, $"{AdminBase}/{_o.Realm}/client-scopes");
            retry.Headers.Add("Authorization", $"Bearer {token}");
            var r2 = await http.SendAsync(retry, ct);
            if (r2.IsSuccessStatusCode)
            {
                var d2 = JsonDocument.Parse(await r2.Content.ReadAsStringAsync(ct));
                if (d2.RootElement.ValueKind == JsonValueKind.Array)
                    foreach (var el in d2.RootElement.EnumerateArray())
                        if (el.TryGetProperty("name", out var n2) && n2.GetString() == ScopeName && el.TryGetProperty("id", out var id2))
                            return id2.GetString() ?? "";
            }
        }
        logger.LogDebug("Failed to create client scope {Scope}: {Status}", ScopeName, createRes.StatusCode);
        return "";
    }

    private async Task EnsureDefaultScopeAsync(string scopeId, string token, CancellationToken ct)
    {
        var realmReq = new HttpRequestMessage(HttpMethod.Get, $"{AdminBase}/{_o.Realm}");
        realmReq.Headers.Add("Authorization", $"Bearer {token}");
        var realmRes = await http.SendAsync(realmReq, ct);
        if (!realmRes.IsSuccessStatusCode) return;
        var realmDoc = JsonDocument.Parse(await realmRes.Content.ReadAsStringAsync(ct));
        if (realmDoc.RootElement.TryGetProperty("defaultDefaultClientScopes", out var scopes) && scopes.ValueKind == JsonValueKind.Array)
            foreach (var s in scopes.EnumerateArray()) if (s.GetString() == ScopeName) return;
        var addReq = new HttpRequestMessage(HttpMethod.Put, $"{AdminBase}/{_o.Realm}/default-default-client-scopes/{Uri.EscapeDataString(scopeId)}");
        addReq.Headers.Add("Authorization", $"Bearer {token}");
        var addRes = await http.SendAsync(addReq, ct);
        if (addRes.IsSuccessStatusCode) logger.LogInformation("Added {Scope} to realm default scopes", ScopeName);
    }

    private async Task<IReadOnlyCollection<string>> ResolveScopeKeysAsync(string token, CancellationToken ct)
    {
        var defaults = new[] { "region","branch","department","organization","warehouse","customer","project","test-key" };
        try
        {
            // Read iam-scope-registry group attributes for scope.<key>
            var req = new HttpRequestMessage(HttpMethod.Get, $"{AdminBase}/{_o.Realm}/groups?search=iam-scope-registry");
            req.Headers.Add("Authorization", $"Bearer {token}");
            var res = await http.SendAsync(req, ct);
            if (!res.IsSuccessStatusCode) return defaults;
            var doc = JsonDocument.Parse(await res.Content.ReadAsStringAsync(ct));
            if (doc.RootElement.ValueKind != JsonValueKind.Array) return defaults;
            foreach (var el in doc.RootElement.EnumerateArray())
            {
                if (el.TryGetProperty("name", out var n) && n.GetString() == "iam-scope-registry")
                {
                    var id = el.TryGetProperty("id", out var gid) ? gid.GetString() : null;
                    JsonElement target = el;
                    if (!string.IsNullOrEmpty(id))
                    {
                        var gReq = new HttpRequestMessage(HttpMethod.Get, $"{AdminBase}/{_o.Realm}/groups/{Uri.EscapeDataString(id)}");
                        gReq.Headers.Add("Authorization", $"Bearer {token}");
                        var gRes = await http.SendAsync(gReq, ct);
                        if (gRes.IsSuccessStatusCode) target = JsonDocument.Parse(await gRes.Content.ReadAsStringAsync(ct)).RootElement;
                    }
                    if (!target.TryGetProperty("attributes", out var attrs) || attrs.ValueKind != JsonValueKind.Object) return defaults;
                    var keys = new List<string>();
                    foreach (var p in attrs.EnumerateObject()) if (p.Name.StartsWith("scope.", StringComparison.Ordinal)) keys.Add(p.Name.Substring("scope.".Length));
                    return keys.Count > 0 ? keys : defaults;
                }
            }
        } catch { }
        return defaults;
    }

    private async Task EnsureAttributeMapperAsync(string scopeId, string scopeKey, string token, CancellationToken ct)
    {
        var mapperName = $"authz-scope-{scopeKey}";
        var listReq = new HttpRequestMessage(HttpMethod.Get, $"{AdminBase}/{_o.Realm}/client-scopes/{Uri.EscapeDataString(scopeId)}/protocol-mappers/models");
        listReq.Headers.Add("Authorization", $"Bearer {token}");
        var listRes = await http.SendAsync(listReq, ct);
        if (listRes.IsSuccessStatusCode)
        {
            var doc = JsonDocument.Parse(await listRes.Content.ReadAsStringAsync(ct));
            if (doc.RootElement.ValueKind == JsonValueKind.Array)
                foreach (var el in doc.RootElement.EnumerateArray())
                    if (el.TryGetProperty("name", out var n) && n.GetString() == mapperName) return;
        }
        var body = new
        {
            name = mapperName,
            protocol = "openid-connect",
            protocolMapper = "oidc-usermodel-attribute-mapper",
            config = new Dictionary<string,string>
            {
                ["user.attribute"] = ScopeAttrPrefix + scopeKey,
                ["claim.name"] = $"authz.scope.{scopeKey}",
                ["jsonType.label"] = "String",
                ["multivalued"] = "true",
                ["aggregate.attrs"] = "true",
                ["userinfo.token.claim"] = "true",
                ["access.token.claim"] = "true",
                ["id.token.claim"] = "false",
            }
        };
        var createReq = new HttpRequestMessage(HttpMethod.Post, $"{AdminBase}/{_o.Realm}/client-scopes/{Uri.EscapeDataString(scopeId)}/protocol-mappers/models") { Content = JsonContent.Create(body) };
        createReq.Headers.Add("Authorization", $"Bearer {token}");
        var createRes = await http.SendAsync(createReq, ct);
        if (!createRes.IsSuccessStatusCode) logger.LogDebug("Failed to create mapper {Mapper}: {Status} {Body}", mapperName, createRes.StatusCode, await createRes.Content.ReadAsStringAsync(ct));
        else logger.LogInformation("Provisioned authz scope mapper {Mapper}", mapperName);
    }
}

using System.Net.Http.Json;
using System.Text.Json;
using Identity.Application.Scope;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using Identity.Infrastructure.Keycloak;

namespace Identity.Infrastructure.Keycloak.Scope;

/// <summary>
/// Scope registry backed by the dedicated config Group <c>iam-scope-registry</c>.
/// Group attributes:
///   scope.&lt;key&gt; = JSON {"displayName":...,"description":...,"isActive":true,"valueType":"String"}
///   resource.&lt;name&gt; = multivalued scope keys (each value = one scope key)
/// Business-role Groups hold <c>authz.allowed-scopes</c> multivalued.
/// Implements <see cref="IScopeDefinitionLookup"/>, <see cref="IResourceScopeResolver"/>, <see cref="IScopeCacheInvalidator"/>.
/// </summary>
public sealed class KeycloakScopeRegistryStore(
    HttpClient http,
    IOptions<KeycloakOptions> opts,
    KeycloakAdminTokenProvider tokenProvider,
    IMemoryCache cache,
    ILogger<KeycloakScopeRegistryStore> logger) : IScopeDefinitionLookup, IResourceScopeResolver, IScopeCacheInvalidator
{
    private readonly KeycloakOptions _o = opts.Value;
    private string AdminBase => $"{_o.BaseUrl.TrimEnd('/')}/admin/realms";
    private const string RegistryGroupName = "iam-scope-registry";
    private const string ActiveKey = "scopes:active:kc:v1";
    private const string RoleAllowedKey = "scopes:roleAllowed:kc:v1";
    private const string ResourceMapKey = "scopes:resourceMap:kc:v1";
    private static readonly TimeSpan Ttl = TimeSpan.FromMinutes(5);

    public void Invalidate()
    {
        cache.Remove(ActiveKey);
        cache.Remove(RoleAllowedKey);
        cache.Remove(ResourceMapKey);
    }

    private sealed record ScopeDef(string Key, string DisplayName, string? Description, bool IsActive, string ValueType);

    private static ScopeDef ParseScope(string key, string json)
    {
        try
        {
            var doc = JsonDocument.Parse(json);
            var display = doc.RootElement.TryGetProperty("displayName", out var d) ? d.GetString() ?? key : key;
            var desc = doc.RootElement.TryGetProperty("description", out var dd) ? dd.GetString() : null;
            var active = doc.RootElement.TryGetProperty("isActive", out var ia) ? ia.GetBoolean() : true;
            var vt = doc.RootElement.TryGetProperty("valueType", out var vt2) ? vt2.GetString() ?? "String" : "String";
            return new ScopeDef(key, display, desc, active, vt);
        }
        catch { return new ScopeDef(key, key, null, true, "String"); }
    }

    private async Task<Dictionary<string, string[]>> GetRegistryAttributesAsync(CancellationToken ct)
    {
        var token = await tokenProvider.GetTokenAsync(ct);
        if (string.IsNullOrEmpty(token)) return new(StringComparer.Ordinal);
        try
        {
            // Find registry group
            var req = new HttpRequestMessage(HttpMethod.Get, $"{AdminBase}/{_o.Realm}/groups?search={Uri.EscapeDataString(RegistryGroupName)}");
            req.Headers.Add("Authorization", $"Bearer {token}");
            var res = await http.SendAsync(req, ct);
            if (!res.IsSuccessStatusCode) return new(StringComparer.Ordinal);
            var doc = JsonDocument.Parse(await res.Content.ReadAsStringAsync(ct));
            if (doc.RootElement.ValueKind != JsonValueKind.Array) return new(StringComparer.Ordinal);
            foreach (var el in doc.RootElement.EnumerateArray())
            {
                var name = el.TryGetProperty("name", out var n) ? n.GetString() : null;
                if (!string.Equals(name, RegistryGroupName, StringComparison.Ordinal)) continue;
                var id = el.TryGetProperty("id", out var gid) ? gid.GetString() : null;
                if (string.IsNullOrEmpty(id)) return AttrsFromElement(el);
                // Fetch full group with attributes
                var gReq = new HttpRequestMessage(HttpMethod.Get, $"{AdminBase}/{_o.Realm}/groups/{Uri.EscapeDataString(id)}");
                gReq.Headers.Add("Authorization", $"Bearer {token}");
                var gRes = await http.SendAsync(gReq, ct);
                if (!gRes.IsSuccessStatusCode) return AttrsFromElement(el);
                var gDoc = JsonDocument.Parse(await gRes.Content.ReadAsStringAsync(ct));
                return AttrsFromElement(gDoc.RootElement);
            }
        }
        catch (Exception ex) { logger.LogDebug(ex, "Failed to fetch scope registry group"); }
        return new(StringComparer.Ordinal);
    }

    private static Dictionary<string, string[]> AttrsFromElement(JsonElement el)
    {
        var d = new Dictionary<string, string[]>(StringComparer.Ordinal);
        if (!el.TryGetProperty("attributes", out var attrs) || attrs.ValueKind != JsonValueKind.Object) return d;
        foreach (var prop in attrs.EnumerateObject())
        {
            if (prop.Value.ValueKind == JsonValueKind.Array)
                d[prop.Name] = prop.Value.EnumerateArray().Select(v => v.GetString() ?? "").Where(s => s.Length > 0).ToArray();
            else if (prop.Value.ValueKind == JsonValueKind.String)
                d[prop.Name] = new[] { prop.Value.GetString() ?? "" };
        }
        return d;
    }

    private async Task<IReadOnlyCollection<ScopeDef>> GetActiveScopesAsync(CancellationToken ct)
    {
        if (cache.TryGetValue(ActiveKey, out IReadOnlyCollection<ScopeDef>? c) && c is not null) return c;
        var attrs = await GetRegistryAttributesAsync(ct);
        var list = new List<ScopeDef>();
        foreach (var kv in attrs)
        {
            if (!kv.Key.StartsWith("scope.", StringComparison.Ordinal)) continue;
            var key = kv.Key.Substring("scope.".Length);
            var json = kv.Value.FirstOrDefault() ?? "{}";
            var def = ParseScope(key, json);
            if (def.IsActive) list.Add(def);
        }
        // Fallback to defaults if registry empty (migration window / no Keycloak): seed-like defaults
        if (list.Count == 0 && attrs.Count == 0)
        {
            // Return in-memory defaults so validation doesn't break when Keycloak unreachable in tests
            foreach (var k in new[] { "region", "branch", "department", "organization", "warehouse", "customer", "project", "test-key" })
                list.Add(new ScopeDef(k, k, null, true, "String"));
        }
        IReadOnlyCollection<ScopeDef> result = list;
        cache.Set(ActiveKey, result, Ttl);
        return result;
    }

    public async Task<bool> ExistsActiveAsync(string key, CancellationToken ct)
    {
        var active = await GetActiveScopesAsync(ct);
        return active.Any(s => string.Equals(s.Key, key, StringComparison.OrdinalIgnoreCase));
    }

    public async Task<bool> IsScopeAllowedForRoleAsync(string role, string scopeKey, CancellationToken ct)
    {
        var map = await GetRoleAllowedMapAsync(ct);
        if (!map.TryGetValue(role, out var allowed)) return true; // no restriction = allow
        if (allowed.Count == 0) return true;
        return allowed.Contains(scopeKey);
    }

    private async Task<Dictionary<string, HashSet<string>>> GetRoleAllowedMapAsync(CancellationToken ct)
    {
        if (cache.TryGetValue(RoleAllowedKey, out Dictionary<string, HashSet<string>>? c) && c is not null) return c;
        var map = new Dictionary<string, HashSet<string>>(StringComparer.OrdinalIgnoreCase);
        var token = await tokenProvider.GetTokenAsync(ct);
        if (!string.IsNullOrEmpty(token))
        {
            try
            {
                // List all business-role groups and read authz.allowed-scopes
                var req = new HttpRequestMessage(HttpMethod.Get, $"{AdminBase}/{_o.Realm}/groups?briefRepresentation=false");
                req.Headers.Add("Authorization", $"Bearer {token}");
                var res = await http.SendAsync(req, ct);
                if (res.IsSuccessStatusCode)
                {
                    var doc = JsonDocument.Parse(await res.Content.ReadAsStringAsync(ct));
                    if (doc.RootElement.ValueKind == JsonValueKind.Array)
                    {
                        foreach (var el in doc.RootElement.EnumerateArray())
                        {
                            var gname = el.TryGetProperty("name", out var n) ? n.GetString() : null;
                            if (string.IsNullOrEmpty(gname) || string.Equals(gname, RegistryGroupName, StringComparison.OrdinalIgnoreCase)) continue;
                            var attrs = AttrsFromElement(el);
                            if (attrs.TryGetValue("authz.allowed-scopes", out var allowed))
                                map[gname] = new HashSet<string>(allowed, StringComparer.OrdinalIgnoreCase);
                            // Also try to fetch full group if brief lacked attributes
                            if (!attrs.ContainsKey("authz.allowed-scopes") && el.TryGetProperty("id", out var gid) && gid.GetString() is string id)
                            {
                                var gReq = new HttpRequestMessage(HttpMethod.Get, $"{AdminBase}/{_o.Realm}/groups/{Uri.EscapeDataString(id)}");
                                gReq.Headers.Add("Authorization", $"Bearer {token}");
                                var gRes = await http.SendAsync(gReq, ct);
                                if (gRes.IsSuccessStatusCode)
                                {
                                    var gDoc = JsonDocument.Parse(await gRes.Content.ReadAsStringAsync(ct));
                                    var gAttrs = AttrsFromElement(gDoc.RootElement);
                                    if (gAttrs.TryGetValue("authz.allowed-scopes", out var gAllowed))
                                        map[gname] = new HashSet<string>(gAllowed, StringComparer.OrdinalIgnoreCase);
                                }
                            }
                        }
                    }
                }
            }
            catch (Exception ex) { logger.LogDebug(ex, "Failed to fetch role allowed scopes"); }
        }
        cache.Set(RoleAllowedKey, map, Ttl);
        return map;
    }

    public async Task<HashSet<string>> GetScopesForResourceAsync(string resourceKey, CancellationToken ct)
    {
        var map = await GetResourceMapAsync(ct);
        return map.TryGetValue(resourceKey, out var set) ? new HashSet<string>(set, StringComparer.OrdinalIgnoreCase) : new HashSet<string>(StringComparer.OrdinalIgnoreCase);
    }

    private async Task<Dictionary<string, HashSet<string>>> GetResourceMapAsync(CancellationToken ct)
    {
        if (cache.TryGetValue(ResourceMapKey, out Dictionary<string, HashSet<string>>? c) && c is not null) return c;
        var attrs = await GetRegistryAttributesAsync(ct);
        var map = new Dictionary<string, HashSet<string>>(StringComparer.OrdinalIgnoreCase);
        // resource.<name> = multivalued scope keys
        foreach (var kv in attrs)
        {
            if (!kv.Key.StartsWith("resource.", StringComparison.Ordinal)) continue;
            var rKey = kv.Key.Substring("resource.".Length);
            map[rKey] = new HashSet<string>(kv.Value, StringComparer.OrdinalIgnoreCase);
        }
        if (map.Count == 0 && attrs.Count == 0)
        {
            // Defaults mirror ScopeSeed
            map["Orders"] = new HashSet<string>(new[] { "region", "branch", "warehouse", "customer" }, StringComparer.OrdinalIgnoreCase);
            map["Branches"] = new HashSet<string>(new[] { "region" }, StringComparer.OrdinalIgnoreCase);
            map["Employees"] = new HashSet<string>(new[] { "region", "branch", "department", "organization" }, StringComparer.OrdinalIgnoreCase);
            map["ProjectTasks"] = new HashSet<string>(new[] { "project" }, StringComparer.OrdinalIgnoreCase);
            map["ProjectDocuments"] = new HashSet<string>(new[] { "project" }, StringComparer.OrdinalIgnoreCase);
            map["CustomerOrders"] = new HashSet<string>(new[] { "customer" }, StringComparer.OrdinalIgnoreCase);
            map["ResourceA"] = new HashSet<string>(new[] { "test-key" }, StringComparer.OrdinalIgnoreCase);
        }
        cache.Set(ResourceMapKey, map, Ttl);
        return map;
    }
}

using System.Text.Json;
using Identity.Application;
using Identity.Contracts;
using Identity.Application.Scope;

namespace Identity.Infrastructure.Keycloak.Scope;

/// <summary>
/// User + Group scope attribute store using namespaced multivalued attributes:
///   user/group attribute authz.scope.&lt;key&gt; — each value is one collection entry.
/// Effective merge: Group scopes ∪ User scopes (union, unique, ordered), gated by
/// authz.allowed-scopes on the business-role Groups at write time.
/// Implements IUserScopeReader / IUserScopeWriter over Keycloak Admin REST.
/// Also provides group-level helpers for EfUserScopeStore migration.
/// </summary>
public sealed class KeycloakScopeAttributeStore(
    HttpClient http,
    Identity.Infrastructure.Keycloak.KeycloakOptions opts,
    KeycloakAdminTokenProvider tokenProvider,
    Identity.Application.ScopedAccessSerializer serializer)
    : IUserScopeReader, IUserScopeWriter
{
    private string AdminBase => $"{opts.BaseUrl.TrimEnd('/')}/admin/realms";
    private const string ScopeAttrPrefix = "authz.scope.";

    private async Task<JsonElement?> GetUserJsonAsync(string userId, string token, CancellationToken ct)
    {
        var req = new HttpRequestMessage(HttpMethod.Get, $"{AdminBase}/{opts.Realm}/users/{Uri.EscapeDataString(userId)}");
        req.Headers.Add("Authorization", $"Bearer {token}");
        try
        {
            var res = await http.SendAsync(req, ct);
            if (!res.IsSuccessStatusCode) return null;
            return JsonDocument.Parse(await res.Content.ReadAsStringAsync(ct)).RootElement.Clone();
        }
        catch { return null; }
    }

    private async Task<bool> PutUserAsync(JsonElement userJson, string token, CancellationToken ct)
    {
        var uid = userJson.TryGetProperty("id", out var p) ? p.GetString() ?? "" : "";
        if (string.IsNullOrEmpty(uid)) return false;
        var req = new HttpRequestMessage(HttpMethod.Put, $"{AdminBase}/{opts.Realm}/users/{Uri.EscapeDataString(uid)}")
        { Content = new StringContent(userJson.GetRawText(), System.Text.Encoding.UTF8, "application/json") };
        req.Headers.Add("Authorization", $"Bearer {token}");
        try { var r = await http.SendAsync(req, ct); return r.IsSuccessStatusCode; } catch { return false; }
    }

    private async Task<IReadOnlyCollection<string>> GetUserGroupsAsync(string userId, string token, CancellationToken ct)
    {
        var req = new HttpRequestMessage(HttpMethod.Get, $"{AdminBase}/{opts.Realm}/users/{Uri.EscapeDataString(userId)}/groups");
        req.Headers.Add("Authorization", $"Bearer {token}");
        try
        {
            var res = await http.SendAsync(req, ct);
            if (!res.IsSuccessStatusCode) return Array.Empty<string>();
            var doc = JsonDocument.Parse(await res.Content.ReadAsStringAsync(ct));
            if (doc.RootElement.ValueKind != JsonValueKind.Array) return Array.Empty<string>();
            return doc.RootElement.EnumerateArray().Select(e => e.TryGetProperty("name", out var n) ? n.GetString() ?? "" : "").Where(s => s.Length>0).ToArray();
        }
        catch { return Array.Empty<string>(); }
    }

    private static Dictionary<string, string[]> ExtractScopeAttrs(JsonElement el)
    {
        var d = new Dictionary<string, string[]>(StringComparer.Ordinal);
        if (!el.TryGetProperty("attributes", out var attrs) || attrs.ValueKind != JsonValueKind.Object) return d;
        foreach (var p in attrs.EnumerateObject())
            if (p.Name.StartsWith(ScopeAttrPrefix, StringComparison.Ordinal))
            {
                var k = p.Name.Substring(ScopeAttrPrefix.Length);
                d[k] = p.Value.ValueKind == JsonValueKind.Array ? p.Value.EnumerateArray().Select(v=>v.GetString()??"").Where(s=>s.Length>0).ToArray()
                    : p.Value.ValueKind == JsonValueKind.String ? new[] { p.Value.GetString()??"" } : Array.Empty<string>();
            }
        return d;
    }

    private static JsonElement SetScopeAttrs(JsonElement userJson, IReadOnlyDictionary<string, IReadOnlyCollection<string>> merged, CancellationToken _)
    {
        // Build new attributes: keep non-scope attrs, replace authz.scope.* from merged
        var doc = JsonDocument.Parse(userJson.GetRawText());
        using var ms = new System.IO.MemoryStream();
        using var w = new System.Text.Json.Utf8JsonWriter(ms);
        w.WriteStartObject();
        bool hasAttrs = doc.RootElement.TryGetProperty("attributes", out var existingAttrs);
        // Write non-attributes props
        foreach (var prop in doc.RootElement.EnumerateObject())
        {
            if (prop.NameEquals("attributes")) continue;
            prop.WriteTo(w);
        }
        w.WritePropertyName("attributes");
        w.WriteStartObject();
        if (hasAttrs && existingAttrs.ValueKind == JsonValueKind.Object)
            foreach (var a in existingAttrs.EnumerateObject())
                if (!a.Name.StartsWith(ScopeAttrPrefix, StringComparison.Ordinal))
                    a.WriteTo(w);
        foreach (var kv in merged.OrderBy(k=>k.Key, StringComparer.Ordinal))
        {
            if (kv.Value.Count==0) continue;
            w.WritePropertyName(ScopeAttrPrefix + kv.Key);
            w.WriteStartArray();
            foreach (var v in kv.Value.OrderBy(x=>x, StringComparer.Ordinal)) w.WriteStringValue(v);
            w.WriteEndArray();
        }
        w.WriteEndObject();
        w.WriteEndObject();
        w.Flush();
        return JsonDocument.Parse(System.Text.Encoding.UTF8.GetString(ms.ToArray())).RootElement.Clone();
    }

    private async Task<Dictionary<string,string[]>> GetGroupScopeAttrsAsync(string groupId, string token, CancellationToken ct)
    {
        var req = new HttpRequestMessage(HttpMethod.Get, $"{AdminBase}/{opts.Realm}/groups/{Uri.EscapeDataString(groupId)}");
        req.Headers.Add("Authorization", $"Bearer {token}");
        try
        {
            var res = await http.SendAsync(req, ct);
            if (!res.IsSuccessStatusCode) return new(StringComparer.Ordinal);
            var doc = JsonDocument.Parse(await res.Content.ReadAsStringAsync(ct));
            return ExtractScopeAttrs(doc.RootElement);
        } catch { return new(StringComparer.Ordinal); }
    }

    private async Task<IReadOnlyCollection<(string name,string id)>> GetUserGroupsWithIdsAsync(string userId, string token, CancellationToken ct)
    {
        var req = new HttpRequestMessage(HttpMethod.Get, $"{AdminBase}/{opts.Realm}/users/{Uri.EscapeDataString(userId)}/groups");
        req.Headers.Add("Authorization", $"Bearer {token}");
        try
        {
            var res = await http.SendAsync(req, ct);
            if (!res.IsSuccessStatusCode) return Array.Empty<(string,string)>();
            var doc = JsonDocument.Parse(await res.Content.ReadAsStringAsync(ct));
            if (doc.RootElement.ValueKind != JsonValueKind.Array) return Array.Empty<(string,string)>();
            return doc.RootElement.EnumerateArray().Select(e => (e.TryGetProperty("name", out var n)?n.GetString()??"":"", e.TryGetProperty("id", out var i)?i.GetString()??"":"")).Where(x=>x.Item1.Length>0).ToArray();
        } catch { return Array.Empty<(string,string)>(); }
    }

    public async Task<ScopedAccessDocument> GetAsync(string userId, CancellationToken ct)
    {
        var token = await tokenProvider.GetTokenAsync(ct);
        if (string.IsNullOrEmpty(token)) return ScopedAccessDocument.Empty;
        var uj = await GetUserJsonAsync(userId, token, ct);
        if (uj is null) return ScopedAccessDocument.Empty;
        var scopeAttrs = ExtractScopeAttrs(uj.Value);
        if (scopeAttrs.Count > 0 || true) // always try group merge; fallback legacy if both empty handled below
        {
            var groups = await GetUserGroupsWithIdsAsync(userId, token, ct);
            // Union group scopes + user scopes per key
            var mergedByKey = new Dictionary<string, HashSet<string>>(StringComparer.Ordinal);
            foreach (var v in scopeAttrs) { if (!mergedByKey.TryGetValue(v.Key, out var s)) { s=new HashSet<string>(StringComparer.Ordinal); mergedByKey[v.Key]=s; } foreach (var x in v.Value) s.Add(x); }
            foreach (var g in groups)
            {
                var gAttrs = await GetGroupScopeAttrsAsync(g.id, token, ct);
                foreach (var kv in gAttrs) { if (!mergedByKey.TryGetValue(kv.Key, out var s)) { s=new HashSet<string>(StringComparer.Ordinal); mergedByKey[kv.Key]=s; } foreach (var x in kv.Value) s.Add(x); }
            }
            if (mergedByKey.Count>0)
            {
                var flat = mergedByKey.ToDictionary(k=>k.Key, v=>(IReadOnlyCollection<string>)v.Value.OrderBy(x=>x,StringComparer.Ordinal).ToArray(), StringComparer.Ordinal);
                // Expose as one doc with one assignment per group (or single) sharing the merged scopes — keeps AccessContext shape
                var byRole = new List<ScopedRoleAssignment>();
                if (groups.Count>0) foreach (var g in groups) byRole.Add(new ScopedRoleAssignment(g.name, flat));
                else byRole.Add(new ScopedRoleAssignment("_user", flat));
                // If legacy attribute also present and groups empty, still return merged; otherwise prefer merged result
                if (byRole.Count>0) return new ScopedAccessDocument(byRole);
            }
            if (scopeAttrs.Count>0)
            {
                // Fallback without group fetch
                var groups2 = await GetUserGroupsAsync(userId, token, ct);
                var byRole2 = new List<ScopedRoleAssignment>();
                foreach (var g in groups2) byRole2.Add(new ScopedRoleAssignment(g, scopeAttrs.ToDictionary(k=>k.Key, v=>(IReadOnlyCollection<string>)v.Value, StringComparer.Ordinal)));
                if (byRole2.Count==0) byRole2.Add(new ScopedRoleAssignment("_user", scopeAttrs.ToDictionary(k=>k.Key, v=>(IReadOnlyCollection<string>)v.Value, StringComparer.Ordinal)));
                return new ScopedAccessDocument(byRole2);
            }
        }
        var raw = ExtractSingleAttr(uj.Value, ScopedAccessConstants.AttributeName);
        if (!string.IsNullOrWhiteSpace(raw)) return serializer.Deserialize(raw);
        return ScopedAccessDocument.Empty;
    }

    public async Task<IReadOnlyDictionary<string, IReadOnlyCollection<string>>> GetEffectiveAsync(string userId, CancellationToken ct)
    {
        var doc = await GetAsync(userId, ct);
        var merged = new Dictionary<string, HashSet<string>>(StringComparer.Ordinal);
        foreach (var a in doc.Assignments) foreach (var kv in a.Scopes)
        {
            if (!merged.TryGetValue(kv.Key, out var set)) { set = new HashSet<string>(StringComparer.Ordinal); merged[kv.Key]=set; }
            foreach (var v in kv.Value) set.Add(v);
        }
        return merged.ToDictionary(k=>k.Key, v=>(IReadOnlyCollection<string>)v.Value.OrderBy(x=>x, StringComparer.Ordinal).ToArray(), StringComparer.Ordinal);
    }

    public async Task SetAsync(string userId, IReadOnlyCollection<ScopedRoleAssignmentDto> assignments, CancellationToken ct)
    {
        // Validate via existing validator semantics (ExistsActive, allowed, value)
        // Caller (ProvisioningOrchestrator) already validated; we re-enforce allow-list here for safety
        var token = await tokenProvider.GetTokenAsync(ct);
        if (string.IsNullOrEmpty(token)) throw new InvalidOperationException("Keycloak admin token unavailable.");
        var uj = await GetUserJsonAsync(userId, token, ct);
        if (uj is null) throw new InvalidOperationException($"User '{userId}' not found.");
        // Merge all assignments' scopes into flat authz.scope.<key> union
        var merged = new Dictionary<string, HashSet<string>>(StringComparer.Ordinal);
        foreach (var a in assignments) foreach (var kv in a.Scopes)
        {
            if (!merged.TryGetValue(kv.Key, out var set)) { set = new HashSet<string>(StringComparer.Ordinal); merged[kv.Key]=set; }
            foreach (var v in kv.Value.Where(s=>!string.IsNullOrWhiteSpace(s)).Select(s=>s.Trim())) set.Add(v);
        }
        var flat = merged.ToDictionary(k=>k.Key, v=>(IReadOnlyCollection<string>)v.Value.OrderBy(x=>x, StringComparer.Ordinal).ToArray(), StringComparer.Ordinal);
        // Also persist legacy attribute for claim-mapper compat during migration
        var doc = new ScopedAccessDocument(assignments.Select(a => new ScopedRoleAssignment(a.Role, a.Scopes.Where(kv=>kv.Value.Count>0).ToDictionary(k=>k.Key, v=>v.Value, StringComparer.Ordinal))).ToArray());
        var withNew = SetScopeAttrs(uj.Value, flat, ct);
        var withBoth = SetSingleAttr(withNew, ScopedAccessConstants.AttributeName, doc.Assignments.Count==0?null:serializer.Serialize(doc));
        var ok = await PutUserAsync(withBoth, token, ct);
        if (!ok) throw new InvalidOperationException($"Failed to update scopes for user '{userId}'.");
    }

    private static string? ExtractSingleAttr(JsonElement el, string name)
    {
        if (!el.TryGetProperty("attributes", out var attrs) || attrs.ValueKind!=JsonValueKind.Object) return null;
        if (!attrs.TryGetProperty(name, out var arr)) return null;
        if (arr.ValueKind==JsonValueKind.Array && arr.GetArrayLength()>0) return arr[0].GetString();
        if (arr.ValueKind==JsonValueKind.String) return arr.GetString();
        return null;
    }
    private static JsonElement SetSingleAttr(JsonElement el, string name, string? value)
    {
        var doc = JsonDocument.Parse(el.GetRawText());
        using var ms = new System.IO.MemoryStream();
        using var w = new System.Text.Json.Utf8JsonWriter(ms);
        w.WriteStartObject();
        bool hasAttrs = doc.RootElement.TryGetProperty("attributes", out var existing);
        foreach (var p in doc.RootElement.EnumerateObject()) if (!p.NameEquals("attributes")) p.WriteTo(w);
        w.WritePropertyName("attributes");
        w.WriteStartObject();
        if (hasAttrs && existing.ValueKind==JsonValueKind.Object)
            foreach (var a in existing.EnumerateObject()) if (!a.NameEquals(name)) a.WriteTo(w);
        if (value is not null) { w.WritePropertyName(name); w.WriteStartArray(); w.WriteStringValue(value); w.WriteEndArray(); }
        w.WriteEndObject();
        w.WriteEndObject();
        w.Flush();
        return JsonDocument.Parse(System.Text.Encoding.UTF8.GetString(ms.ToArray())).RootElement.Clone();
    }
}

