1	using Identity.Application;
2	using Identity.Application.Scope;
3	using Identity.Contracts;
4	using Identity.Persistence.KeyManagement;
5	using Microsoft.EntityFrameworkCore;
6	using Microsoft.Extensions.Caching.Memory;
7	
8	namespace Identity.Sample.Tests;
9	
10	/// <summary>18 scenarios for the DB-driven dynamic scope system.</summary>
11	public sealed class DynamicScopeTests
12	{
13	    private static KeyMetadataDbContext InMemoryDb()
14	    {
15	        var opts = new DbContextOptionsBuilder<KeyMetadataDbContext>()
16	            .UseInMemoryDatabase(Guid.NewGuid().ToString())
17	            .Options;
18	        var db = new KeyMetadataDbContext(opts);
19	        db.Database.EnsureCreated();
20	        return db;
21	    }
22	
23	    private static async Task SeedAsync(KeyMetadataDbContext db)
24	        => await ScopeSeed.EnsureSeededAsync(db, CancellationToken.None);
25	
26	    private sealed class FakeRoleStore : IBusinessRoleStore
27	    {
28	        private readonly HashSet<string> _roles;
29	        public FakeRoleStore(params string[] roles) => _roles = new HashSet<string>(roles, StringComparer.Ordinal);
30	        public Task<BusinessRoleDto?> GetAsync(string name, CancellationToken ct) => Task.FromResult(_roles.Contains(name) ? new BusinessRoleDto(name, null, true, Array.Empty<string>()) : null);
31	        public Task<IReadOnlyCollection<BusinessRoleDto>> ListAsync(CancellationToken ct) => Task.FromResult((IReadOnlyCollection<BusinessRoleDto>)_roles.Select(r => new BusinessRoleDto(r, null, true, Array.Empty<string>())).ToArray());
32	        public Task<BusinessRoleDto> CreateAsync(string name, string? desc, IReadOnlyCollection<string> perms, CancellationToken ct) { _roles.Add(name); return Task.FromResult(new BusinessRoleDto(name, desc, true, perms.ToArray())); }
33	        public Task<BusinessRoleDto?> UpdateAsync(string name, string? desc, CancellationToken ct) => Task.FromResult<BusinessRoleDto?>(null);
34	        public Task<bool> DeleteAsync(string name, CancellationToken ct) => Task.FromResult(_roles.Remove(name));
35	        public Task<IReadOnlyCollection<string>> GetEffectivePermissionsAsync(string name, CancellationToken ct) => Task.FromResult((IReadOnlyCollection<string>)Array.Empty<string>());
36	        public Task AddPermissionsAsync(string name, IReadOnlyCollection<string> perms, CancellationToken ct) => Task.CompletedTask;
37	        public Task RemovePermissionAsync(string name, string perm, CancellationToken ct) => Task.CompletedTask;
38	    }
39	
40	    // 1 valid dynamic scope
41	    [Fact]
42	    public async Task Scenario01_ValidDynamicScope_Passes()
43	    {
44	        using var db = InMemoryDb(); await SeedAsync(db);
45	        var cache = new MemoryCache(new MemoryCacheOptions());
